async function requestTeacherRole(){
 const u=current();if(isAdmin()||u.role==='teacher'){toast('Tài khoản của bạn đã có quyền giáo viên hoặc quản trị viên.');return}
 const sb=window.studyloadSupabase;
 const {data:pending,error:checkError}=await sb.from('teacher_requests').select('id').eq('user_id',u.id).eq('status','pending').limit(1);
 if(checkError){toast('Không kiểm tra được yêu cầu: '+checkError.message);return}
 if(pending?.length){toast('Bạn đã gửi yêu cầu. Vui lòng chờ quản trị viên duyệt.');return}
 const message=[u.name,u.email,u.studentCode||'',u.className||''].join(' | ');
 const {error}=await sb.from('teacher_requests').insert({user_id:u.id,message,status:'pending'});
 if(error){toast('Không gửi được yêu cầu: '+error.message);return}
 toast('Đã gửi yêu cầu quyền giáo viên. Quản trị viên sẽ xem xét.');
}
async function renderAdminRequests(){
 if(!isAdmin())return;
 const root=$('#adminRequests');if(!root)return;
 const {data:reqs,error}=await window.studyloadSupabase.from('teacher_requests').select('id,user_id,message,status,created_at').eq('status','pending').order('created_at',{ascending:true});
 if(error){root.innerHTML='<div class="card span-12"><h2>Yêu cầu quyền giáo viên</h2><div class="notice red">'+esc(error.message)+'</div></div>';return}
 root.innerHTML=`<div class="card span-12"><h2>Yêu cầu quyền giáo viên</h2>${(reqs||[]).map(r=>`<div class="item"><div><div class="item-title">${esc(r.message||r.user_id)} <span class="badge amber">Chờ duyệt</span></div><div class="item-meta">${fmtDate(r.created_at)}</div></div><div class="actions"><button class="small" data-approve-teacher="${r.id}">Phê duyệt</button><button class="small danger" data-reject-teacher="${r.id}">Từ chối</button></div></div>`).join('')||'<div class="empty">Không có yêu cầu đang chờ.</div>'}<p class="footer-note">Yêu cầu được lưu trong Supabase và chỉ quản trị viên có quyền duyệt.</p></div>`;
 root.querySelectorAll('[data-approve-teacher]').forEach(b=>b.onclick=()=>decideTeacherRequest(b.dataset.approveTeacher,true));
 root.querySelectorAll('[data-reject-teacher]').forEach(b=>b.onclick=()=>decideTeacherRequest(b.dataset.rejectTeacher,false));
}
async function decideTeacherRequest(id,approve){
 if(!isAdmin())return;
 const {error}=await window.studyloadSupabase.rpc('admin_review_teacher_request',{target_request_id:id,decision:approve?'approved':'rejected',note:null});
 if(error){toast('Không cập nhật được yêu cầu: '+error.message);return}
 const {data:profile}=await window.studyloadSupabase.from('profiles').select('*').eq('id',current().id).single();
 if(profile){current().role=profile.role||current().role;render()}
 await renderAdminRequests();toast(approve?'Đã phê duyệt quyền giáo viên.':'Đã từ chối yêu cầu.');
}
function adminOnlyAction(action){if(!isAdmin()){toast('Chỉ tài khoản quản trị viên mới dùng được chức năng này.');return false}return true}
function toast(s){$('#toastRoot').innerHTML=`<div class="toast">${esc(s)}</div>`;setTimeout(()=>$('#toastRoot').innerHTML='',2800)}
function taskStatus(t){if(t.status==='done')return 'Hoàn thành';if(new Date(t.dueAt)<now())return 'Chưa hoàn thành – Quá hạn';return t.status==='doing'?'Đang làm':'Chưa làm'}
function activeTasks(owner=current().id){return state.tasks.filter(t=>t.ownerId===owner&&t.status!=='done'&&new Date(t.dueAt)>=now())}
function overdueTasks(owner=current().id){return state.tasks.filter(t=>t.ownerId===owner&&t.status!=='done'&&new Date(t.dueAt)<now())}
function sessionsFor(t){return (t.sessions||[]).filter(s=>s.endAt&&s.minutes>0)}
function actualFor(t){return (t.sessions||[]).reduce((a,s)=>a+(+s.minutes||0),0)}
function futureSession(s){return !s.completed&&new Date(s.startAt)>now()}
function addMinutes(d,m){return new Date(new Date(d).getTime()+m*60000)}
function dayStart(d){let x=new Date(d);x.setHours(0,0,0,0);return x}
function rangesForDay(date,ownerId){
 let start=dayStart(date),end=new Date(start.getTime()+DAY),free=[];
 // Demo default availability 16:00-22:00 on weekdays, 09:00-22:00 weekends; subtract busy blocks.
 let dow=start.getDay(), baseStart=new Date(start),baseEnd=new Date(start);
 baseStart.setHours(dow===0||dow===6?9:16,0,0,0);baseEnd.setHours(22,0,0,0);
 free.push([baseStart,baseEnd]);
 for(let b of state.busy.filter(x=>x.ownerId===ownerId)){
  if(!b.days?.includes(dow))continue;
  let [sh,sm]=b.start.split(':').map(Number),[eh,em]=b.end.split(':').map(Number);
  let bs=new Date(start);bs.setHours(sh,sm,0,0);let be=new Date(start);be.setHours(eh,em,0,0);if(be<=bs)be=new Date(be.getTime()+DAY);
  for(let offset of [0,1]){let a=new Date(bs.getTime()+offset*DAY),z=new Date(be.getTime()+offset*DAY);if(a<end&&z>start){let aa=new Date(Math.max(a,start)),zz=new Date(Math.min(z,end));free=subtractRange(free,aa,zz)}}
 }
 // Subtract completed/past time and all fixed past sessions; future scheduled sessions get regenerated by scheduler.
 let cutStart=new Date(Math.max(start.getTime(),now().getTime()));
 free=free.map(([a,b])=>[new Date(Math.max(a,cutStart)),b]).filter(([a,b])=>b>a);
 return free;
}
function subtractRange(ranges,a,b){let out=[];for(let [s,e] of ranges){if(b<=s||a>=e){out.push([s,e]);continue}if(a>s)out.push([s,a]);if(b<e)out.push([b,e])}return out}
function scheduledMinutes(t){return (t.sessions||[]).filter(s=>!s.completed&&new Date(s.startAt)>now()).reduce((n,s)=>n+s.minutes,0)}
function schedule(ownerId=current().id){
 let ts=state.tasks.filter(t=>t.ownerId===ownerId&&t.status!=='done');
 // Preserve completed/history and only rebuild future planned sessions.
 ts.forEach(t=>t.sessions=(t.sessions||[]).filter(s=>s.completed||new Date(s.startAt)<=now()));
 let pending=ts.filter(t=>new Date(t.dueAt)>=now()).sort((a,b)=>new Date(a.dueAt)-new Date(b.dueAt)||(b.priority||0)-(a.priority||0));
 let days={};let first=dayStart(now());let last=Math.max(...pending.map(t=>dayStart(new Date(t.dueAt)).getTime()),first.getTime());
 for(let stamp=first.getTime();stamp<=last;stamp+=DAY){let d=new Date(stamp);days[localDay(d)]=rangesForDay(d,ownerId)}
 for(let t of pending){
  let remaining=Math.max(0,Number(t.remainingWorkMinutes)||0);
  // Existing current-day time and past planned sessions are immutable; only place remaining work in future free ranges.
  for(let stamp=first.getTime();stamp<=dayStart(new Date(t.dueAt)).getTime()&&remaining>0;stamp+=DAY){
   let day=new Date(stamp),key=localDay(day),ranges=days[key]||rangesForDay(day,ownerId);
   let due=new Date(t.dueAt);
   for(let i=0;i<ranges.length&&remaining>0;i++){
    let [a,b]=ranges[i];a=new Date(Math.max(a,now()));b=new Date(Math.min(b,due));if(b<=a)continue;
    let available=Math.floor((b-a)/60000);if(available<=0)continue;
    let take=Math.min(remaining,available,90);
    if(take>0){t.sessions.push({id:uid('s'),startAt:iso(a),endAt:iso(addMinutes(a,take)),minutes:take,completed:false,planned:true});remaining-=take;ranges[i]=[addMinutes(a,take),b]}
   }
   days[key]=ranges;
  }
  t.unscheduledMinutes=remaining;
 }
 state.tasks.filter(t=>t.ownerId===ownerId&&new Date(t.dueAt)<now()&&t.status!=='done').forEach(t=>{t.status='overdue';t.unscheduledMinutes=t.remainingWorkMinutes||0});
 save();
}
function capacityForDay(date,ownerId=current().id){return rangesForDay(date,ownerId).reduce((n,[a,b])=>n+Math.max(0,Math.floor((b-a)/60000)),0)}
function loadForDay(date,ownerId=current().id){let k=localDay(date);return state.tasks.filter(t=>t.ownerId===ownerId&&t.status!=='done').reduce((n,t)=>n+(t.sessions||[]).filter(s=>localDay(s.startAt)===k&&!s.completed&&new Date(s.startAt)>now()).reduce((a,s)=>a+s.minutes,0),0)}
function riskTasks(ownerId=current().id){return activeTasks(ownerId).filter(t=>(t.unscheduledMinutes||0)>0)}
function taskCard(t){let risk=(t.unscheduledMinutes||0)>0,studyMinutes=t.status==='done'?(Number(t.actualMinutes)||0):(Number(t.remainingWorkMinutes??t.estimatedMinutes)||0);return `<div class="item"><div class="item-main"><div class="item-title">${esc(t.title)} ${risk?'<span class="badge red">Có thể trễ hạn</span>':''}</div><div class="item-meta"><b>Học ${fmtMinutes(studyMinutes)}</b></div><div class="item-meta">${esc(t.subject)} · Hạn nộp: ${fmtDate(t.dueAt)} · Còn cần học: ${fmtMinutes(t.remainingWorkMinutes)} · Đã học: ${fmtMinutes(t.actualMinutes)}</div><div class="item-meta"><span class="badge ${t.status==='done'?'green':risk?'red':' '}">${esc(taskStatus(t))}</span> <span class="badge">Mức ưu tiên: ${esc(t.priority===3?'Cao':t.priority===2?'Vừa':'Thường')}</span></div></div><div class="actions"><button class="small" data-action="detail" data-id="${t.id}">Xem chi tiết</button>${isStudent()&&t.status!=='done'?`<button class="small secondary" data-action="study" data-id="${t.id}">Bắt đầu học</button><button class="small secondary" data-action="complete" data-id="${t.id}">Đánh dấu hoàn thành</button>`:''}${isTeacher()?`<button class="small secondary" data-action="edit-task" data-id="${t.id}">Sửa nhiệm vụ</button>`:''}</div></div>`}
function pageHead(title,sub){$('#pageTitle').textContent=title;$('#subtitle').textContent=sub}
function render(){
 const u=current();$('#userSelect').innerHTML=`<option value="${u.id}">${esc(u.name)} · ${isAdmin()?'Admin':isTeacher()?'Giáo viên':'Học sinh'}</option>`;
 $$('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
 if(page==='dashboard')renderDashboard();if(page==='tasks')renderTasks();if(page==='calendar')renderCalendar();if(page==='classes')renderClasses();if(page==='class-tools')renderClassTools();if(page==='library')renderLibrary();if(page==='reports')renderReports();if(page==='notifications')renderNotifications();if(page==='settings')renderSettings();
}
function renderDashboard(){let u=current();pageHead('Tổng quan',isTeacher()?'Theo dõi nhiệm vụ đã giao, hạn nộp và tiến độ của học sinh.':'Xem việc cần làm, lịch học và thời gian đã học.');let tasks=isStudent()?activeTasks(u.id):teacherTasks(u);let risks=isStudent()?riskTasks(u.id):tasks.filter(t=>(t.unscheduledMinutes||0)>0);let dueSoon=tasks.filter(t=>new Date(t.dueAt)-now()<DAY);let mins=state.tasks.filter(t=>isStudent()?t.ownerId===u.id:allowedTaskIds(u).has(t.id)).reduce((n,t)=>n+(+t.actualMinutes||0),0);
 $('#content').innerHTML=`<div class="grid">
 <div class="card span-3"><div class="stat-label">Nhiệm vụ chưa hoàn thành</div><div class="stat">${tasks.length}</div><div class="muted">${isTeacher()?`Đang theo dõi ${tasks.length} nhiệm vụ đã giao`:`Còn ${tasks.length} nhiệm vụ chưa làm`}</div></div>
 <div class="card span-3"><div class="stat-label">Thời gian học đã xác nhận</div><div class="stat">${Math.round(mins/60*10)/10}h</div><div class="muted">Tổng thời gian đã xác nhận</div></div>
 <div class="card span-3"><div class="stat-label">Hạn nộp trong 24 giờ</div><div class="stat">${dueSoon.length}</div><div class="muted">Cần ưu tiên kiểm tra</div></div>
 <div class="card span-3"><div class="stat-label">Có thể trễ hạn</div><div class="stat">${risks.length}</div><div class="muted">Dựa trên sức chứa trước hạn</div></div>
 <div class="card span-7"><div class="section-head"><h2>Nhiệm vụ cần chú ý</h2><button class="secondary small" data-goto="tasks">Xem tất cả</button></div>${risks.length?'<div class="notice red">Có nhiệm vụ có nguy cơ trễ hạn.</div>'+risks.map(taskCard).join(''): '<div class="notice green">Chưa phát hiện nhiệm vụ thiếu sức chứa trước hạn trong dữ liệu hiện tại.</div>'}${tasks.filter(t=>!risks.includes(t)).slice(0,3).map(taskCard).join('')||''}</div>
 <div class="card ${isTeacher()?'span-12':'span-5'}"><h2>${isTeacher()?'Tiến độ từng học sinh':'Khối lượng học trong 7 ngày tới'}</h2>${isTeacher()?classProgress(state.classes.filter(c=>isAdmin()||c.teacherIds.includes(u.id))):loadChart(u.id,7)}<div class="footer-note">${isTeacher()?'Số liệu dựa trên các nhiệm vụ thuộc lớp bạn phụ trách.':'Mức tải được tính từ thời gian đã xếp lịch so với thời gian có thể học. Thời gian bận và thời gian đã qua không được tính.'}</div></div>
 <div class="card span-6"><h2>${isTeacher()?'Nhiệm vụ sắp đến hạn':'Lịch học sắp tới'}</h2>${isTeacher()?tasks.slice().sort((a,b)=>new Date(a.dueAt)-new Date(b.dueAt)).slice(0,5).map(taskCard).join('')||'<div class="empty">Chưa có nhiệm vụ cần theo dõi.</div>':upcomingSessions(u.id)}</div>
 <div class="card span-6"><h2>Thông báo gần đây</h2>${notificationList(state.notifications.filter(n=>n.userId===u.id).slice(-4).reverse())}</div>
 </div>`;
}
function teacherTasks(u){let allowed=allowedTaskIds(u);return state.tasks.filter(t=>allowed.has(t.id)&&t.status!=='done'&&new Date(t.dueAt)>=now())}
function allowedTaskIds(u){let ids=new Set();state.tasks.forEach(t=>{let homeroom=state.classes.some(c=>c.id===t.classId&&(c.homeroomTeacherIds||[]).includes(u.id));if(u.role==='admin'||(u.role==='teacher'&&(t.teacherId===u.id||homeroom)&&(!u.subject||t.subject===u.subject)))ids.add(t.id)});return ids}
function loadChart(owner,days){let start=dayStart(now()),arr=[];for(let i=0;i<days;i++){let d=new Date(start.getTime()+i*DAY),cap=capacityForDay(d,owner),load=loadForDay(d,owner),pct=cap?Math.min(150,load/cap*100):0;arr.push({d,cap,load,pct})}return `<div class="chart">${arr.map(x=>`<div class="chart-col"><div class="chart-val">${x.cap?Math.round(x.pct)+'%':'—'}</div><div class="chart-bar ${x.pct>100?'over':''}" style="height:${Math.max(2,x.pct/150*135)}px" title="Đã phân bổ ${x.load} phút / sức chứa ${x.cap} phút"></div><div class="chart-label">${x.d.toLocaleDateString('vi-VN',{weekday:'short',day:'numeric'})}</div></div>`).join('')}</div>`}
function upcomingSessions(owner){let arr=state.tasks.filter(t=>t.ownerId===owner&&t.status!=='done').flatMap(t=>(t.sessions||[]).filter(s=>!s.completed&&new Date(s.startAt)>now()).map(s=>({t,s}))).sort((a,b)=>new Date(a.s.startAt)-new Date(b.s.startAt)).slice(0,5);return arr.length?arr.map(({t,s})=>`<div class="item"><div><div class="item-title">${esc(t.title)}</div><div class="item-meta">${fmtDate(s.startAt)} · ${s.minutes} phút</div></div><button class="small secondary" data-action="detail" data-id="${t.id}">Chi tiết</button></div>`).join(''):'<div class="empty">Chưa có buổi học nào được xếp lịch sắp tới.</div>'}
function dayLabel(key){let today=localDay(now()),tomorrow=localDay(new Date(dayStart(now()).getTime()+DAY));if(key===today)return 'HÔM NAY';if(key===tomorrow)return 'NGÀY MAI';let d=new Date(key+'T12:00:00');return d.toLocaleDateString('vi-VN',{weekday:'long',day:'numeric',month:'long'}).toLocaleUpperCase('vi-VN')}
function extraStudyAvailability(ownerId=current().id){let cap=capacityForDay(now(),ownerId),load=loadForDay(now(),ownerId);return Math.max(0,cap-load)}
function extraStudyPrompt(tasks){if(!isStudent())return '';let today=localDay(now()),tomorrow=localDay(new Date(dayStart(now()).getTime()+DAY)),todayTasks=tasks.filter(t=>localDay(t.dueAt)===today),tomorrowTasks=tasks.filter(t=>localDay(t.dueAt)===tomorrow&&t.status!=='done'),available=extraStudyAvailability(current().id);if(!todayTasks.length||!todayTasks.every(t=>t.status==='done')||!tomorrowTasks.length||available<=0||extraPromptDismissedDay===today)return '';if(extraStudyChooser){let selected=tomorrowTasks.filter(t=>t.status!=='done'),total=selected.filter(t=>$('#taskList input[data-extra-id="'+t.id+'"]')?.checked).reduce((n,t)=>n+(Number(t.remainingWorkMinutes)||Number(t.estimatedMinutes)||0),0);return `<div class="card" style="margin-top:12px"><h2>Bạn đã hoàn thành xong nhiệm vụ hôm nay</h2><p>Bạn có muốn làm bài tập của ngày mai không?</p><p>Chọn những nhiệm vụ muốn làm trước. Thời gian còn trống hôm nay: <b>${available} phút</b>.</p><div class="stack">${selected.map(t=>`<label class="checkrow"><input type="checkbox" data-extra-id="${t.id}" data-minutes="${Number(t.remainingWorkMinutes)||Number(t.estimatedMinutes)||0}"> <span>${esc(t.subject)} — ${esc(t.title)} <span class="muted">(${Number(t.remainingWorkMinutes)||Number(t.estimatedMinutes)||0} phút)</span></span></label>`).join('')}</div><div id="extraOverload" class="notice red ${total>available?'':'hidden'}" style="margin-top:10px">Cảnh báo quá tải: bạn chọn ${total} phút nhưng hôm nay chỉ còn ${available} phút.</div><div class="row" style="margin-top:12px"><button data-action="confirm-extra-study">Xếp lịch và học</button><button class="secondary" data-action="extra-study-no">Không</button></div></div>`}return `<div class="card" style="margin-top:12px"><p style="margin:0 0 8px"><b>Bạn đã hoàn thành xong nhiệm vụ hôm nay</b></p><p style="margin:0 0 12px">Bạn có muốn làm bài tập của ngày mai không?</p><div class="row"><button data-action="extra-study-yes">Có</button><button class="secondary" data-action="extra-study-no">Không</button></div></div>`}
function renderTasks(){let u=current();pageHead(isTeacher()?'Nhiệm vụ đã giao':'Nhiệm vụ của tôi',isTeacher()?'Theo dõi hạn nộp, tiến độ và những nhiệm vụ cần hỗ trợ.':'Nhiệm vụ được chia theo ngày để bạn dễ theo dõi.');let tasks=isStudent()?state.tasks.filter(t=>t.ownerId===u.id):state.tasks.filter(t=>allowedTaskIds(u).has(t.id));$('#content').innerHTML=`<div class="section-head"><div class="row"><input id="taskSearch" placeholder="Tìm theo tên nhiệm vụ hoặc môn học…" style="width:240px"><select id="taskFilter" style="width:170px"><option value="all">Tất cả</option><option value="todo">Chưa bắt đầu</option><option value="doing">Đang làm</option><option value="done">Hoàn thành</option><option value="overdue">Quá hạn</option><option value="risk">Có nguy cơ trễ hạn</option></select></div>${isStudent()?'<button data-action="new-task">+ Tạo nhiệm vụ cá nhân</button>':''}</div><div id="taskList" class="stack"></div>`;function draw(){let q=$('#taskSearch').value.toLowerCase(),f=$('#taskFilter').value;let arr=tasks.filter(t=>(t.title+' '+t.subject).toLowerCase().includes(q));if(f==='done')arr=arr.filter(t=>t.status==='done');if(f==='todo')arr=arr.filter(t=>t.status==='todo');if(f==='doing')arr=arr.filter(t=>t.status==='doing');if(f==='overdue')arr=arr.filter(t=>t.status!=='done'&&new Date(t.dueAt)<now());if(f==='risk')arr=arr.filter(t=>(t.unscheduledMinutes||0)>0);arr.sort((a,b)=>new Date(a.dueAt)-new Date(b.dueAt));let groups={};arr.forEach(t=>{let k=localDay(t.dueAt);(groups[k]??=[]).push(t)});let grouped=Object.entries(groups).map(([k,items])=>`<section class="day-task-group"><h2 class="day-task-heading">${dayLabel(k)} <span class="muted" style="font-size:12px;font-weight:500">· ${items.length} nhiệm vụ</span></h2><div class="stack">${items.map(taskCard).join('')}</div></section>`).join('');let prompt=extraStudyPrompt(tasks);$('#taskList').innerHTML=(extraOverloadNotice?`<div class="notice red">${esc(extraOverloadNotice)}</div>`:'')+(grouped||'<div class="empty">Không tìm thấy nhiệm vụ phù hợp.</div>')+prompt;let boxes=$$('#taskList input[data-extra-id]');if(boxes.length){let updateWarning=()=>{let total=boxes.filter(x=>x.checked).reduce((n,x)=>n+(Number(x.dataset.minutes)||0),0),avail=extraStudyAvailability(u.id),warning=$('#extraOverload');if(warning){warning.classList.toggle('hidden',total<=avail);warning.textContent=`Cảnh báo quá tải: bạn chọn ${total} phút nhưng hôm nay chỉ còn ${avail} phút.`}};boxes.forEach(x=>x.addEventListener('change',updateWarning));updateWarning()}}$('#taskSearch').oninput=draw;$('#taskFilter').onchange=draw;draw()}
function renderCalendar(){let u=current();pageHead(isTeacher()?'Lịch nhiệm vụ':'Lịch học cá nhân',isTeacher()?'Xem hạn nộp các nhiệm vụ đã giao.':'Xem lịch học, hạn nộp và thời gian bận của bạn.');let base=new Date(state.viewDate||localDay(now()));let start=new Date(base);if(calendarMode==='week'){start.setDate(start.getDate()-((start.getDay()+6)%7));}else start.setDate(1);let count=calendarMode==='week'?7:new Date(start.getFullYear(),start.getMonth()+1,0).getDate();let days=Array.from({length:count},(_,i)=>new Date(start.getTime()+i*DAY));$('#content').innerHTML=`<div class="card"><div class="section-head"><div class="row"><button class="secondary" data-action="cal-prev">←</button><h2>${start.toLocaleDateString('vi-VN',{month:'long',year:'numeric'})}${calendarMode==='week'?' · tuần':''}</h2><button class="secondary" data-action="cal-next">→</button></div><div class="row"><button class="${calendarMode==='week'?'':'secondary'}" data-action="cal-week">Tuần</button><button class="${calendarMode==='month'?'':'secondary'}" data-action="cal-month">Tháng</button><button class="secondary" data-action="busy">+ Thời gian bận</button></div></div><div class="weekdays">${['T2','T3','T4','T5','T6','T7','CN'].map(x=>`<div>${x}</div>`).join('')}</div><div class="calendar">${days.map(d=>{let k=localDay(d),ts=state.tasks.filter(t=>t.ownerId===u.id&&t.status!=='done'&&localDay(t.dueAt)===k),ss=state.tasks.filter(t=>t.ownerId===u.id).flatMap(t=>(t.sessions||[]).filter(s=>localDay(s.startAt)===k).map(s=>({t,s})));return `<div class="day ${k===localDay(now())?'today':''}"><h3>${d.toLocaleDateString('vi-VN',{day:'numeric',month:calendarMode==='week'?'short':undefined})}</h3>${ss.map(({t,s})=>`<div class="cal-event ${s.completed?'done':''}" data-action="detail" data-id="${t.id}" title="${esc(t.title)}">${s.completed?'✓ ':''}${new Date(s.startAt).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})} ${esc(t.title)}</div>`).join('')}${ts.map(t=>`<div class="cal-event" data-action="detail" data-id="${t.id}" title="Hạn nộp">${esc(t.title)} · Hạn</div>`).join('')}</div>`}).join('')}</div><div class="footer-note">Giờ hiển thị theo múi giờ thiết bị. Kế hoạch trong tương lai được tính lại khi lịch bận hoặc tiến độ thay đổi.</div></div><div class="card" style="margin-top:16px"><h2>Thời gian bận lặp lại</h2>${state.busy.filter(b=>b.ownerId===u.id).map(b=>`<div class="item"><div><div class="item-title">${esc(b.label)}</div><div class="item-meta">${b.start}–${b.end} · ${b.days.map(d=>['CN','T2','T3','T4','T5','T6','T7'][d]).join(', ')}</div></div><button class="small danger" data-action="delete-busy" data-id="${b.id}">Xóa</button></div>`).join('')||'<div class="empty">Chưa khai báo thời gian bận.</div>'}</div>`}
function renderClasses(){let u=current();pageHead('Lớp học & dự án','Giao nhiệm vụ, tổ chức nhóm và quản lý minh chứng.');let classes=state.classes.filter(c=>isAdmin()||(u.role==='teacher'?c.teacherIds.includes(u.id):c.studentIds.includes(u.id)));$('#content').innerHTML=`<div class="grid"><div class="card span-5"><div class="section-head"><h2>Lớp học</h2>${isAdmin()?'<button class="small" data-action="new-class">+ Tạo lớp</button>':''}</div>${classes.map(c=>`<div class="item"><div><div class="item-title">${esc(c.name)}</div><div class="item-meta">${c.studentIds.length} học sinh · ${c.teacherIds.length} giáo viên</div><div class="item-meta">${c.studentIds.map(id=>esc(state.users.find(x=>x.id===id)?.name||'')).join(', ')}</div></div>${isTeacher()?`<button class="small secondary" data-action="assign" data-id="${c.id}">Giao nhiệm vụ</button>`:''}${isAdmin()?`<button class="small secondary" data-action="manage-class" data-id="${c.id}">Quản lý</button>`:''}</div>`).join('')||'<div class="empty">Chưa có lớp trong phạm vi tài khoản này.</div>'}</div><div class="card span-7"><div class="section-head"><h2>Dự án nhóm</h2>${isTeacher()?'<button data-action="new-project">+ Tạo dự án</button>':''}</div>${state.projects.filter(p=>classes.some(c=>c.id===p.classId)||p.memberIds?.includes(u.id)||p.teacherIds?.includes(u.id)).map(projectCard).join('')||'<div class="empty">Chưa có dự án. Giáo viên có thể tạo dự án cho lớp.</div>'}</div><div class="card span-12"><h2>Báo cáo tiến độ lớp</h2>${classProgress(classes)}</div></div>`}
function projectCard(p){return `<div class="item"><div><div class="item-title">${esc(p.name)}</div><div class="item-meta">${esc(state.classes.find(c=>c.id===p.classId)?.name||'')} · ${p.groups.length} nhóm · ${p.tasks.length} nhiệm vụ</div><div class="item-meta">${p.groups.map(g=>esc(g.name)+' ('+g.memberIds.length+')').join(' · ')}</div></div><div class="actions"><button class="small secondary" data-action="project-detail" data-id="${p.id}">Mở dự án</button></div></div>`}
function classProgress(classes){let viewer=current(),visibleTask=t=>t.classId===undefined?false:(viewer.role!=='teacher'||((t.teacherId===viewer.id||classes.some(c=>c.id===t.classId&&(c.homeroomTeacherIds||[]).includes(viewer.id)))&&(!viewer.subject||t.subject===viewer.subject)));let cs=classes.flatMap(c=>state.tasks.filter(t=>t.classId===c.id&&visibleTask(t)));if(!classes.some(c=>c.studentIds.length)||!cs.length)return '<div class="empty">Chưa có dữ liệu nhiệm vụ của lớp.</div>';return `<div class="table-wrap"><table><thead><tr><th>Lớp</th><th>Học sinh</th><th>Đã giao</th><th>Đã hoàn thành</th><th>Đang làm</th><th>Chưa bắt đầu</th><th>Tiến độ</th><th>Thời gian đã học</th></tr></thead><tbody>${classes.flatMap(c=>c.studentIds.map(id=>{let ts=state.tasks.filter(t=>t.ownerId===id&&t.classId===c.id&&visibleTask(t)),done=ts.filter(t=>t.status==='done').length,doing=ts.filter(t=>t.status==='doing').length,todo=ts.filter(t=>t.status==='todo').length,mins=ts.reduce((n,t)=>n+(+t.actualMinutes||0),0),pct=ts.length?Math.round(done/ts.length*100):0;return `<tr><td>${esc(c.name)}</td><td>${esc(state.users.find(u=>u.id===id)?.name||'Học sinh')}</td><td>${ts.length}</td><td>${done}</td><td>${doing}</td><td>${todo}</td><td>${pct}%</td><td>${mins} phút</td></tr>`})).join('')}</tbody></table></div>`}
function hasOfficer(role,classId=toolClassId){return (state.officerRoles||[]).some(x=>x.class_id===classId&&x.user_id===current().id&&x.role===role&&!x.ended_at)}
function canManageDuties(classId=toolClassId){return isAdmin()||state.classes.some(c=>c.id===classId&&(c.homeroomTeacherIds||[]).includes(current().id))||hasOfficer('labor_vp',classId)}
function canManageOfficers(classId=toolClassId){return isAdmin()||state.classes.some(c=>c.id===classId&&(c.homeroomTeacherIds||[]).includes(current().id))}
function canPostAnnouncement(classId=toolClassId){return isAdmin()||state.classes.some(c=>c.id===classId&&(c.homeroomTeacherIds||[]).includes(current().id))||hasOfficer('class_president',classId)}
