 html+='<div class="card span-6"><div class="section-head"><h2>Lịch trực</h2>'+(canManageDuties(c.id)?'<button class="small" id="addDuty">+ Xếp lịch</button>':'')+'</div>'+(duties.map(d=>'<div class="item"><div><div class="item-title">'+esc(d.duty_type)+' · '+esc(d.duty_date)+'</div><div class="item-meta">'+esc(state.users.find(x=>x.id===d.student_id)?.name||'Học sinh')+' · '+(dutyNames[d.status]||d.status)+' · '+esc(d.note||'')+'</div><div class="item-meta">'+ev.filter(x=>x.duty_schedule_id===d.id).length+' minh chứng</div>'+ev.filter(x=>x.duty_schedule_id===d.id).map(x=>'<button class="small secondary" data-duty-file-open="'+x.id+'">'+esc(x.note||'Mở minh chứng')+'</button>').join('')+'</div><div class="actions">'+(d.student_id===u.id&&d.status!=='approved'?'<button class="small secondary" data-duty-submit="'+d.id+'">Nộp minh chứng</button>':'')+(canManageDuties(c.id)&&d.status==='submitted'?'<button class="small" data-duty-approve="'+d.id+'">Duyệt</button><button class="small danger" data-duty-reject="'+d.id+'">Yêu cầu sửa</button>':'')+'</div></div>').join('')||'<div class="empty">Chưa có lịch trực.</div>')+'</div>';
 html+='<div class="card span-6"><div class="section-head"><h2>Nhiệm vụ cán sự</h2>'+(canManageOfficers(c.id)||hasOfficer('class_president',c.id)||hasOfficer('academic_vp',c.id)||hasOfficer('labor_vp',c.id)?'<button class="small" id="addOfficerTask">+ Giao việc</button>':'')+'</div>'+(tasks.map(t=>'<div class="item"><div><div class="item-title">'+esc(t.title)+'</div><div class="item-meta">'+esc(t.category)+' · '+esc(state.users.find(x=>x.id===t.assigned_to)?.name||'Chưa giao')+' · '+esc(t.status)+'</div></div>'+(t.assigned_to===u.id&&t.status!=='completed'?'<button class="small" data-officer-done="'+t.id+'">Hoàn thành</button>':'')+'</div>').join('')||'<div class="empty">Chưa có nhiệm vụ cán sự.</div>')+'</div>';
