 html+='<div class="card span-6"><div class="section-head"><h2>Báo cáo tuần</h2>'+(canManageOfficers(c.id)||hasOfficer('class_president',c.id)?'<button class="small" id="weeklyReport">+ Lập báo cáo</button>':'')+'</div>'+(reports.map(r=>'<div class="item"><div><div class="item-title">'+esc(r.week_start)+' – '+esc(r.week_end)+'</div><div class="item-meta">'+esc(r.comments||'Chưa có nhận xét')+'</div></div></div>').join('')||'<div class="empty">Chưa có báo cáo tuần.</div>')+'</div>';
