 $('[data-duty-submit]').forEach(b=>b.onclick=()=>dutyEvidenceForm(b.dataset.dutySubmit));$('[data-duty-file-open]').forEach(b=>b.onclick=async()=>{const x=ev.find(z=>z.id===b.dataset.dutyFileOpen);if(!x?.file_path)return;const {data,error}=await window.studyloadSupabase.storage.from('duty-evidence').createSignedUrl(x.file_path,60);if(error){toast(error.message);return}window.open(data.signedUrl,'_blank','noopener')});$$('[data-duty-approve]').forEach(b=>b.onclick=()=>reviewDuty(b.dataset.dutyApprove,'approve'));$$('[data-duty-reject]').forEach(b=>b.onclick=()=>reviewDuty(b.dataset.dutyReject,'reject'));$$('[data-officer-done]').forEach(b=>b.onclick=()=>updateOfficerTask(b.dataset.officerDone));$$('[data-delegate-role]').forEach(b=>b.onclick=()=>delegateRoleForm(c,roles.find(x=>x.id===b.dataset.delegateRole)));$$('[data-revoke-role]').forEach(b=>b.onclick=()=>revokeOfficer(b.dataset.revokeRole));$$('[data-revoke-delegation]').forEach(b=>b.onclick=()=>revokeDelegation(b.dataset.revokeDelegation));$$('[data-team-update]').forEach(b=>b.onclick=()=>teamWeeklyForm(teams.find(x=>x.id===b.dataset.teamUpdate)));
