function announcementForm(c){modal('Đăng thông báo lớp','<form id="announcementForm"><label>Tiêu đề *</label><input name="title" required><label>Nội dung *</label><textarea name="content" required rows="4"></textarea><label>Hết hạn</label><input name="expires" type="datetime-local"><label class="checkrow"><input type="checkbox" name="pinned"> Ghim</label></form>');$('#modalSubmit').onclick=async()=>{let f=$('#announcementForm');if(!f.reportValidity())return;let d=new FormData(f),r=await window.studyloadSupabase.from('class_announcements').insert({class_id:c.id,title:d.get('title'),content:d.get('content'),posted_by:current().id,is_pinned:d.has('pinned'),expires_at:d.get('expires')?new Date(d.get('expires')).toISOString():null});if(r.error){toast(r.error.message);return}c.studentIds.filter(id=>id!==current().id).forEach(id=>notifyUser(id,'Thông báo lớp mới',d.get('title'),'announcement'));closeModal();await reloadStudyLoadDomain();renderClassTools()}}
function dutyForm(c){let people=c.studentIds.map(id=>'<option value="'+esc(id)+'">'+esc(state.users.find(x=>x.id===id)?.name||'Học sinh')+'</option>').join(''),teams=(state.classTeams||[]).filter(t=>t.class_id===c.id).map(t=>'<option value="'+esc(t.id)+'">'+esc(t.name)+'</option>').join('');modal('Xếp lịch trực','<form id="dutyForm"><label>Học sinh *</label><select name="student" required>'+people+'</select><label>Nhóm</label><select name="team"><option value="">Không chọn</option>'+teams+'</select><label>Ngày *</label><input type="date" name="date" required value="'+localDay(now())+'"><label>Loại công việc</label><select name="type"><option value="cleaning">Vệ sinh</option><option value="classroom">Trực nhật lớp</option><option value="equipment">Thiết bị</option><option value="other">Khác</option></select><label>Ghi chú</label><textarea name="note"></textarea></form>');$('#modalSubmit').onclick=async()=>{let f=$('#dutyForm');if(!f.reportValidity())return;let d=new FormData(f),r=await window.studyloadSupabase.rpc('create_duty_schedule',{p_class_id:c.id,p_student_id:d.get('student'),p_duty_date:d.get('date'),p_duty_type:d.get('type'),p_team_id:d.get('team')||null,p_note:d.get('note')||null});if(r.error){toast(r.error.message);return}notifyUser(d.get('student'),'Lịch trực mới',d.get('type')+' · '+d.get('date'),'duty',r.data);closeModal();await reloadStudyLoadDomain();renderClassTools()}}
function dutyEvidenceForm(id){modal('Nộp minh chứng trực','<form id="dutyEvidenceForm"><label>Tệp (tối đa 5 MB)</label><input type="file" name="file" accept="image/*,.pdf,.doc,.docx,.txt"><label>Ghi chú</label><textarea name="note"></textarea></form>');$('#modalSubmit').onclick=async()=>{let f=$('#dutyEvidenceForm'),file=f.elements.file.files[0],note=new FormData(f).get('note'),path=null;if(!file&&!String(note||'').trim()){toast('Chọn tệp hoặc nhập ghi chú.');return}if(file){if(file.size>5*1024*1024){toast('Tệp vượt 5 MB.');return}path=current().id+'/'+id+'/'+Date.now()+'_'+file.name.replace(/[^a-zA-Z0-9._-]/g,'_');let up=await window.studyloadSupabase.storage.from('duty-evidence').upload(path,file);if(up.error){toast(up.error.message);return}}let r=await window.studyloadSupabase.rpc('submit_duty_evidence',{p_duty_schedule_id:id,p_file_path:path,p_note:String(note||'').trim()||null});if(r.error){toast(r.error.message);return}closeModal();await reloadStudyLoadDomain();renderClassTools()}}
