function officerTaskForm(c){let people=c.studentIds.map(id=>'<option value="'+esc(id)+'">'+esc(state.users.find(x=>x.id===id)?.name||'Học sinh')+'</option>').join(''),teams=(state.classTeams||[]).filter(t=>t.class_id===c.id).map(t=>'<option value="'+esc(t.id)+'">'+esc(t.name)+'</option>').join('');modal('Giao nhiệm vụ cán sự','<form id="officerTaskForm"><label>Tiêu đề *</label><input name="title" required><label>Mô tả</label><textarea name="description"></textarea><label>Loại</label><select name="category"><option value="academic">Học tập</option><option value="labor">Lao động</option><option value="culture">Văn hóa</option><option value="general">Chung</option></select><label>Giao cho</label><select name="student"><option value="">Chưa chỉ định</option>'+people+'</select><label>Nhóm</label><select name="team"><option value="">Không chọn</option>'+teams+'</select><label>Ưu tiên</label><select name="priority"><option value="normal">Bình thường</option><option value="high">Cao</option><option value="low">Thấp</option></select><label>Hạn</label><input name="due" type="datetime-local"></form>');$('#modalSubmit').onclick=async()=>{let f=$('#officerTaskForm');if(!f.reportValidity())return;let d=new FormData(f),r=await window.studyloadSupabase.rpc('create_officer_task',{p_class_id:c.id,p_title:d.get('title'),p_description:d.get('description')||null,p_category:d.get('category'),p_assigned_to:d.get('student')||null,p_team_id:d.get('team')||null,p_priority:d.get('priority'),p_due_at:d.get('due')?new Date(d.get('due')).toISOString():null});if(r.error){toast(r.error.message);return}if(d.get('student'))notifyUser(d.get('student'),'Nhiệm vụ cán sự mới',d.get('title'),'officer-task',r.data);closeModal();await reloadStudyLoadDomain();renderClassTools()}}
