function officerRoleForm(c){let people=c.studentIds.map(id=>'<option value="'+esc(id)+'">'+esc(state.users.find(x=>x.id===id)?.name||'Học sinh')+'</option>').join('');modal('Phân công cán sự','<form id="roleForm"><label>Vai trò</label><select name="role"><option value="class_president">Lớp trưởng</option><option value="academic_vp">Lớp phó học tập</option><option value="labor_vp">Lớp phó lao động</option></select><label>Học sinh</label><select name="student">'+people+'</select></form>');$('#modalSubmit').onclick=async()=>{let d=new FormData($('#roleForm')),r=await window.studyloadSupabase.rpc('assign_class_officer',{p_class_id:c.id,p_user_id:d.get('student'),p_role:d.get('role'),p_team_id:null});if(r.error){toast(r.error.message);return}closeModal();await reloadStudyLoadDomain();renderClassTools()}}
