function delegateRoleForm(c,role){let people=c.studentIds.filter(id=>id!==role.user_id).map(id=>'<option value="'+esc(id)+'">'+esc(state.users.find(x=>x.id===id)?.name||'Học sinh')+'</option>').join('');modal('Ủy quyền cán sự','<form id="delegationForm"><label>Người nhận</label><select name="to">'+people+'</select><label>Bắt đầu</label><input type="datetime-local" name="start" required value="'+new Date().toISOString().slice(0,16)+'"><label>Kết thúc</label><input type="datetime-local" name="end" required><label>Lý do</label><textarea name="reason"></textarea></form>');$('#modalSubmit').onclick=async()=>{let f=$('#delegationForm');if(!f.reportValidity())return;let d=new FormData(f),start=new Date(d.get('start')),end=new Date(d.get('end'));if(end<=start){toast('Thời điểm kết thúc phải sau bắt đầu.');return}let r=await window.studyloadSupabase.rpc('delegate_class_officer',{p_officer_role_id:role.id,p_delegated_to:d.get('to'),p_starts_at:start.toISOString(),p_ends_at:end.toISOString(),p_reason:d.get('reason')||null});if(r.error){toast(r.error.message);return}closeModal();await reloadStudyLoadDomain();renderClassTools()}}
