function weeklyReportForm(c){let m=new Date(now());m.setDate(m.getDate()-((m.getDay()+6)%7));let start=localDay(m),e=new Date(m);e.setDate(e.getDate()+6);let end=localDay(e);modal('Lập báo cáo tuần','<form id="weeklyForm"><label>Tuần bắt đầu</label><input type="date" name="start" required value="'+start+'"><label>Tuần kết thúc</label><input type="date" name="end" required value="'+end+'"><label>Chuyên cần</label><textarea name="attendance"></textarea><label>Bài tập</label><textarea name="homework"></textarea><label>Lao động / trực</label><textarea name="duty"></textarea><label>Sự kiện</label><textarea name="event"></textarea><label>Nhận xét</label><textarea name="comments"></textarea></form>');$('#modalSubmit').onclick=async()=>{let f=$('#weeklyForm');if(!f.reportValidity())return;let d=new FormData(f),r=await window.studyloadSupabase.from('class_weekly_reports').upsert({class_id:c.id,week_start:d.get('start'),week_end:d.get('end'),created_by:current().id,attendance_summary:{text:d.get('attendance')},homework_summary:{text:d.get('homework')},duty_summary:{text:d.get('duty')},event_summary:{text:d.get('event')},comments:d.get('comments')||null},{onConflict:'class_id,week_start'});if(r.error){toast(r.error.message);return}closeModal();await reloadStudyLoadDomain();renderClassTools()}}
function teamWeeklyForm(team){let m=new Date(now());m.setDate(m.getDate()-((m.getDay()+6)%7));let week=localDay(m),old=(state.teamWeeklyUpdates||[]).find(x=>x.team_id===team.id&&x.user_id===current().id&&x.week_start===week);modal('Cập nhật tuần nhóm','<form id="teamWeeklyForm"><label>Đã hoàn thành</label><textarea name="completed">'+esc(old?.completed_text||'')+'</textarea><label>Kế hoạch</label><textarea name="planned">'+esc(old?.planned_text||'')+'</textarea><label>Khó khăn</label><textarea name="blocker">'+esc(old?.blocker_text||'')+'</textarea></form>');$('#modalSubmit').onclick=async()=>{let d=new FormData($('#teamWeeklyForm')),r=await window.studyloadSupabase.from('team_weekly_updates').upsert({team_id:team.id,user_id:current().id,week_start:week,completed_text:d.get('completed'),planned_text:d.get('planned'),blocker_text:d.get('blocker')},{onConflict:'team_id,user_id,week_start'});if(r.error){toast(r.error.message);return}closeModal();await reloadStudyLoadDomain();renderClassTools()}}
function renderLibrary(){
 let u=current(),items=state.libraries[u.id]||[];
 pageHead('Thư viện','Tài liệu cá nhân lưu trữ riêng tư, có thể chia sẻ theo từng tài khoản.');
 $('#content').innerHTML='<div class="grid"><div class="card span-7"><div class="section-head"><h2>Thư viện cá nhân</h2><button data-action="add-file">+ Thêm tài liệu</button></div><p class="muted">Tệp tải lên được lưu trong Supabase Storage riêng tư (tối đa 5 MB). Quyền chia sẻ được kiểm soát ở cấp bản ghi và tệp.</p>'+items.filter(x=>x.ownerId===u.id).map(x=>'<div class="item"><div><div class="item-title">'+esc(x.name)+'</div><div class="item-meta">'+esc(x.description||'')+(x.url?' · <a href="'+esc(x.url)+'" target="_blank" rel="noopener">Mở liên kết</a>':'')+'</div><div class="item-meta">Chia sẻ với: '+((x.sharedWith||[]).map(id=>esc(state.users.find(z=>z.id===id)?.name||id)).join(', ')||'Chỉ mình tôi')+'</div></div><div class="actions">'+(x.filePath?'<button class="small secondary" data-library-open="'+x.id+'">Mở tệp</button>':'')+'<button class="small secondary" data-action="edit-file" data-id="'+x.id+'">Sửa</button><button class="small danger" data-action="delete-file" data-id="'+x.id+'">Xóa</button></div></div>').join('')||'<div class="empty">Chưa có tài liệu.</div>'+'</div><div class="card span-5"><h2>Được chia sẻ với tôi</h2>'+items.filter(x=>x.ownerId!==u.id).map(x=>'<div class="item"><div><div class="item-title">'+esc(x.name)+'</div><div class="item-meta">Chủ sở hữu: '+esc(state.users.find(z=>z.id===x.ownerId)?.name||'Người dùng')+'</div></div>'+(x.filePath?'<button class="small secondary" data-library-open="'+x.id+'">Mở</button>':'')+'</div>').join('')||'<div class="empty">Chưa có tài liệu được chia sẻ.</div>'+'</div><div class="card span-12"><h2>Tài liệu dự án & minh chứng</h2>'+state.projects.filter(p=>p.memberIds?.includes(u.id)||p.teacherIds?.includes(u.id)||p.groups.some(g=>g.memberIds.includes(u.id))).map(p=>'<div class="item"><div><div class="item-title">'+esc(p.name)+'</div><div class="item-meta">'+p.resources.length+' tài liệu · '+p.evidence.length+' minh chứng</div></div><button class="small secondary" data-action="project-detail" data-id="'+p.id+'">Mở</button></div>').join('')||'<div class="empty">Chưa có tài liệu dự án.</div>'+'</div></div>';
 $('[data-library-open]').forEach(btn=>btn.onclick=async()=>{const x=items.find(y=>y.id===btn.dataset.libraryOpen);if(!x?.filePath)return;const {data,error}=await window.studyloadSupabase.storage.from('study-library').createSignedUrl(x.filePath,60);if(error){toast('Không mở được tệp: '+error.message);return}window.open(data.signedUrl,'_blank','noopener')});
}
function renderReports(){let u=current();pageHead('Báo cáo','Thống kê dựa trên thời gian xác nhận, tiến độ và lịch sử nhiệm vụ.');if(isTeacher()&&!isAdmin()&&!u.homeroom){let allowed=allowedTaskIds(u),ts=state.tasks.filter(t=>allowed.has(t.id));$('#content').innerHTML=`<div class="notice">Báo cáo giáo viên bộ môn chỉ bao gồm lớp, môn học và nhiệm vụ được phân công. Không hiển thị báo cáo thói quen liên môn.</div><div class="grid"><div class="card span-6"><h2>Thời gian thực tế theo nhiệm vụ</h2>${teacherReport(ts)}</div><div class="card span-6"><h2>Gợi ý thời lượng</h2>${teacherSuggestions(ts)}</div><div class="card span-12"><h2>Báo cáo lớp</h2>${classProgress(state.classes.filter(c=>isAdmin()||c.teacherIds.includes(u.id)))}</div></div>`;return}
let ts=isStudent()?state.tasks.filter(t=>t.ownerId===u.id):state.tasks.filter(t=>state.classes.filter(c=>c.teacherIds.includes(u.id)&&c.studentIds.includes(t.ownerId)).length);let completed=ts.filter(t=>t.status==='done'),actual=ts.reduce((n,t)=>n+(+t.actualMinutes||0),0),estimated=ts.reduce((n,t)=>n+(+t.estimatedMinutes||0),0),dev=actual-estimated;
$('#content').innerHTML=`<div class="grid"><div class="card span-3"><div class="stat-label">Tổng thời gian thực tế</div><div class="stat">${Math.round(actual/60*10)/10}h</div></div><div class="card span-3"><div class="stat-label">Thời gian dự kiến</div><div class="stat">${Math.round(estimated/60*10)/10}h</div></div><div class="card span-3"><div class="stat-label">Sai lệch</div><div class="stat">${dev>0?'+':''}${dev} phút</div><div class="muted">${dev<0?'Nhanh hơn dự kiến':dev>0?'Lâu hơn dự kiến':'Khớp dự kiến'}</div></div><div class="card span-3"><div class="stat-label">Đã hoàn thành</div><div class="stat">${completed.length}/${ts.length}</div></div><div class="card span-7"><h2>Thời gian học theo ngày trong tuần</h2>${weekdayChart(ts)}</div><div class="card span-5"><h2>Phân tích thói quen</h2>${habitAdvice(ts)}</div><div class="card span-12"><div class="section-head"><h2>Lịch sử chu kỳ nửa tuần</h2><button class="secondary" data-action="close-cycle">Chốt chu kỳ hiện tại</button></div>${cycleHistory()}</div><div class="card span-12"><h2>Sai lệch theo nhiệm vụ</h2>${deviationTable(ts)}</div></div>`}
function teacherReport(ts){return `<div class="stat">${ts.reduce((n,t)=>n+(+t.actualMinutes||0),0)} phút</div><p class="muted">Tổng thời gian thực tế đã xác nhận trong phạm vi nhiệm vụ được phân công.</p>${deviationTable(ts)}`}
function halfWeekRange(date=now()){let d=new Date(date);d.setHours(0,0,0,0);let dow=d.getDay(),daysFromMonday=(dow+6)%7;let monday=new Date(d);monday.setDate(d.getDate()-daysFromMonday);let thursday=new Date(monday);thursday.setDate(monday.getDate()+3);let start=d<thursday?monday:thursday;let end=new Date(start);end.setDate(start.getDate()+(start.getTime()===monday.getTime()?3:4));return {start,end,label:(start.getTime()===monday.getTime()?'Thứ Hai – Thứ Tư':'Thứ Năm – Chủ Nhật')+' · '+start.toLocaleDateString('vi-VN')+'–'+new Date(end.getTime()-1).toLocaleDateString('vi-VN')}}
function completionDate(t){if(t.completedAt&&Number.isFinite(Date.parse(t.completedAt)))return new Date(t.completedAt);let h=(t.history||[]).filter(x=>x.field==='complete').sort((a,b)=>Date.parse(b.at)-Date.parse(a.at))[0];if(h&&Number.isFinite(Date.parse(h.at)))return new Date(h.at);let ss=(t.sessions||[]).filter(x=>x.completed&&Number.isFinite(Date.parse(x.startAt))).sort((a,b)=>Date.parse(b.startAt)-Date.parse(a.startAt))[0];return ss?new Date(ss.startAt):null}
function teacherSuggestions(ts){let range=halfWeekRange(),completed=ts.filter(t=>t.status==='done'&&Number(t.actualMinutes)>0).map(t=>({t,date:completionDate(t)})).filter(x=>x.date&&x.date>=range.start&&x.date<range.end).map(x=>x.t);if(!completed.length)return `<div class="notice"><b>Không có bài hoàn thành trong chu kỳ này.</b><p>Chu kỳ hiện tại: ${esc(range.label)}. Khi có ít nhất một bài hoàn thành và ghi nhận thời gian thực tế, hệ thống sẽ tính gợi ý ngay, kể cả chỉ có 1 bài.</p><p>Dữ liệu gợi ý được làm mới theo chu kỳ nửa tuần; lịch sử nhiệm vụ vẫn được giữ nguyên.</p></div>`;let groups={};completed.forEach(t=>{let k=(t.subject||'Chưa rõ môn')+' · '+(t.kind||'Nhiệm vụ');(groups[k]??=[]).push(Number(t.actualMinutes))});let rows=Object.entries(groups).map(([k,a])=>`<div class="item"><div><div class="item-title">${esc(k)}</div><div class="item-meta">${a.length} ${a.length===1?'bài':'bài'} hoàn thành trong chu kỳ · thời gian trung bình ${Math.round(a.reduce((n,v)=>n+v,0)/a.length)} phút</div></div><span class="badge green">${a.length===1?'Ước tính ban đầu':'Có dữ liệu'}</span></div>`);return `<p class="muted">Dữ liệu chu kỳ: ${esc(range.label)}. Gợi ý được tính ngay từ bài hoàn thành; chỉ có 1 bài thì lấy thời gian bài đó làm mức trung bình.</p>${rows.join('')}<div class="footer-note">Gợi ý chỉ tham khảo, không tự thay đổi thời lượng giáo viên đặt. Sang chu kỳ nửa tuần mới, phép tính bắt đầu lại; dữ liệu cũ không bị xóa.</div>`}
function median(a){let x=[...a].sort((a,b)=>a-b);return Math.round(x[Math.floor(x.length/2)])}
function weekdayChart(ts){let a=Array(7).fill(0);ts.forEach(t=>(t.sessions||[]).forEach(s=>{if(s.minutes>0&&s.endAt){a[new Date(s.startAt).getDay()]+=s.minutes}}));let max=Math.max(1,...a);return `<div class="chart">${a.map((n,i)=>`<div class="chart-col"><div class="chart-val">${n}m</div><div class="chart-bar" style="height:${Math.max(2,n/max*130)}px"></div><div class="chart-label">${['CN','T2','T3','T4','T5','T6','T7'][i]}</div></div>`).join('')}</div><div class="footer-note">Chỉ cộng phiên có ngày học ghi nhận; thời gian nhập thủ công không có ngày học được ghi vào ngày hoàn thành.</div>`}
function habitAdvice(ts){let completed=ts.filter(t=>t.status==='done'),range=halfWeekRange(),recent=ts.filter(t=>t.status==='done'&&Number(t.actualMinutes)>0).map(t=>({t,date:completionDate(t)})).filter(x=>x.date&&x.date>=range.start&&x.date<range.end).map(x=>x.t),avg=recent.length?Math.round(recent.reduce((n,t)=>n+(+t.actualMinutes||0),0)/recent.length):null,over=ts.filter(t=>t.status==='overdue'||(t.status!=='done'&&new Date(t.dueAt)<now())),long=ts.filter(t=>t.actualMinutes>t.estimatedMinutes&&t.actualMinutes>0);let hours={};ts.forEach(t=>(t.sessions||[]).forEach(s=>{if(s.minutes>0){let h=new Date(s.startAt).getHours(),key=h<12?'Buổi sáng':h<17?'Buổi chiều':'Buổi tối';hours[key]=(hours[key]||0)+s.minutes}}));let best=Object.entries(hours).sort((a,b)=>b[1]-a[1])[0];return `<p>Hoàn thành ${completed.length}/${ts.length} nhiệm vụ có dữ liệu.</p><p><b>Gợi ý thời gian thực tế trong chu kỳ nửa tuần (${esc(range.label)}):</b> ${recent.length?`${avg} phút/bài trung bình từ ${recent.length} bài hoàn thành${recent.length===1?' (ước tính ban đầu)':''}.`:'Không có bài hoàn thành trong chu kỳ này.'}</p><p>${over.length?`Có ${over.length} nhiệm vụ quá hạn hoặc chưa hoàn thành sau hạn.`:'Chưa ghi nhận nhiệm vụ quá hạn trong tập dữ liệu này.'}</p><p>${long.length?`${long.length} nhiệm vụ mất nhiều thời gian hơn dự kiến.`:'Chưa thấy nhiệm vụ vượt dự kiến trong dữ liệu đã xác nhận.'}</p><p>${best?`Khung giờ có nhiều phút học ghi nhận nhất: <b>${best[0]}</b> (${best[1]} phút).`:'Chưa đủ phiên học có dấu thời gian để phân tích khung giờ.'}</p><div class="footer-note">Phân tích mô tả, không dùng điểm số và không tự điều chỉnh lịch.</div>`}
function deviationTable(ts){return `<div class="table-wrap"><table><thead><tr><th>Nhiệm vụ</th><th>Môn / dạng</th><th>Dự kiến</th><th>Thực tế</th><th>Sai lệch</th></tr></thead><tbody>${ts.map(t=>`<tr><td>${esc(t.title)}</td><td>${esc(t.subject)} / ${esc(t.kind||'Khác')}</td><td>${t.estimatedMinutes} phút</td><td>${t.actualMinutes} phút</td><td>${t.actualMinutes-t.estimatedMinutes>0?'+':''}${t.actualMinutes-t.estimatedMinutes} phút</td></tr>`).join('')}</tbody></table></div>`}
function cycleHistory(){let hist=state.cycleHistory||[];return hist.length?hist.slice().reverse().map(c=>`<div class="item"><div><div class="item-title">${esc(c.label)}</div><div class="item-meta">${c.taskCount} nhiệm vụ · ${c.actualMinutes} phút thực tế · sai lệch ${c.deviationMinutes>0?'+':''}${c.deviationMinutes} phút</div></div><span class="badge">Đã lưu</span></div>`).join(''):'<div class="empty">Chưa có chu kỳ nào được chốt. Chu kỳ hiện hành tự bắt đầu khi có dữ liệu.</div>'}
function renderNotifications(){let u=current(),ns=state.notifications.filter(n=>n.userId===u.id).slice().reverse();pageHead('Thông báo','Nhắc hạn cục bộ, cảnh báo và hoạt động dự án.');$('#content').innerHTML=`<div class="section-head"><div class="muted">Nhắc hạn mặc định: 24 giờ và 2 giờ trước hạn. Không có thông báo đẩy khi ứng dụng đóng.</div><button class="secondary" data-action="mark-read">Đánh dấu đã đọc</button></div><div class="card"><h2>Hộp thư thông báo</h2>${notificationList(ns)}</div><div class="card" style="margin-top:16px"><h2>Kiểm tra nhắc hạn</h2><p class="muted">Ứng dụng kiểm tra khi đang mở; thông báo lỗi thời sẽ bị bỏ qua. Nếu bật “Chỉ nhắc trong thời gian học”, thông báo thường được xếp hàng tới khung rảnh tiếp theo.</p><button data-action="check-reminders">Kiểm tra ngay</button></div>`}
function notificationList(ns){return ns.length?ns.map(n=>`<div class="item"><div><div class="item-title">${esc(n.title)} ${n.read?'':'<span class="badge">Mới</span>'}</div><div>${esc(n.body)}</div><div class="item-meta">${fmtDate(n.createdAt)}</div></div>${n.read?'':'<button class="small secondary" data-action="read-notice" data-id="${n.id}">Đã đọc</button>'}</div>`).join(''):'<div class="empty">Không có thông báo.</div>'}
async function renderAdminUsers(){
 if(!isAdmin())return;
 const anchor=$('#adminRequests');if(!anchor)return;
 let rows=state.users.filter(x=>x.email||x.username);
 const html='<div class="card span-12" id="adminUsers"><div class="section-head"><h2>Quản lý tài khoản</h2><span class="muted">'+rows.length+' tài khoản trong dữ liệu đã tải</span></div><input id="adminUserSearch" placeholder="Tìm theo tên, email hoặc username"><div id="adminUserRows">'+rows.map(x=>'<div class="item"><div><div class="item-title">'+esc(x.name)+' '+(x.id===current().id?'<span class="badge">Bạn</span>':'')+'</div><div class="item-meta">'+esc(x.email||x.username||x.id)+' · '+esc(x.role)+'</div></div><div class="actions">'+(x.id===current().id?'': '<select data-user-role="'+x.id+'"><option value="student" '+(x.role==='student'?'selected':'')+'>Học sinh</option><option value="teacher" '+(x.role==='teacher'?'selected':'')+'>Giáo viên</option><option value="admin" '+(x.role==='admin'?'selected':'')+'>Admin</option></select><button class="small secondary" data-user-edit="'+x.id+'">Sửa tên</button><button class="small '+(x.is_banned?'':'danger')+'" data-user-ban="'+x.id+'" data-banned="'+(x.is_banned?'true':'false')+'">'+(x.is_banned?'Mở khóa':'Khóa')+'</button>')+'</div></div>').join('')+'</div></div>';
 anchor.insertAdjacentHTML('afterend',html);
 const search=$('#adminUserSearch');search.oninput=()=>$('#adminUserRows .item').forEach(el=>el.style.display=el.textContent.toLowerCase().includes(search.value.toLowerCase())?'':'none');
 $$('[data-user-role]').forEach(el=>el.onchange=async()=>{if(!confirm('Thay đổi vai trò tài khoản này?')){el.value=state.users.find(x=>x.id===el.dataset.userRole)?.role||'student';return}const r=await window.studyloadSupabase.rpc('admin_set_user_role',{target_user_id:el.dataset.userRole,new_role:el.value});if(r.error){toast(r.error.message);return}await reloadStudyLoadDomain();renderSettings();toast('Đã cập nhật vai trò.')});
 $$('[data-user-ban]').forEach(el=>el.onclick=async()=>{const ban=el.dataset.banned!=='true';if(!confirm(ban?'Khóa tài khoản này?':'Mở khóa tài khoản này?'))return;const r=await window.studyloadSupabase.rpc('admin_set_user_banned',{target_user_id:el.dataset.userBan,ban_status:ban});if(r.error){toast(r.error.message);return}await reloadStudyLoadDomain();renderSettings();toast(ban?'Đã khóa tài khoản.':'Đã mở khóa tài khoản.')});
 $$('[data-user-edit]').forEach(el=>el.onclick=()=>editAdminProfile(el.dataset.userEdit));
}
function editAdminProfile(id){
 const u=state.users.find(x=>x.id===id);if(!u)return;
 modal('Sửa hồ sơ người dùng','<form id="adminProfileForm"><label>Tên hiển thị *</label><input name="name" required value="'+esc(u.name)+'"><label>Username</label><input name="username" required minlength="3" maxlength="30" pattern="[a-z0-9_]+" value="'+esc(u.username||'')+'"><label>Giao diện</label><select name="theme"><option value="system" '+(u.theme==='system'?'selected':'')+'>Theo hệ thống</option><option value="light" '+(u.theme==='light'?'selected':'')+'>Sáng</option><option value="dark" '+(u.theme==='dark'?'selected':'')+'>Tối</option></select></form>');
 $('#modalSubmit').onclick=async()=>{const f=$('#adminProfileForm');if(!f.reportValidity())return;const d=new FormData(f),r=await window.studyloadSupabase.rpc('admin_update_user_profile',{target_user_id:id,new_username:d.get('username'),new_display_name:d.get('name'),new_theme:d.get('theme')});if(r.error){toast(r.error.message);return}closeModal();await reloadStudyLoadDomain();renderSettings();toast('Đã cập nhật hồ sơ.')};
}
function renderSubjectManager(){
 const anchor=$('#adminRequests');if(!anchor)return;
 const html='<div class="card span-12" id="subjectManager"><div class="section-head"><h2>Môn học</h2><button class="small" id="addSubject">+ Tạo môn học</button></div>'+(state.subjects||[]).map(x=>'<div class="item"><div class="item-title">'+esc(x.name)+'</div><div class="item-meta">'+esc(x.description||'')+'</div></div>').join('')+'</div>';
 anchor.insertAdjacentHTML('afterend',html);
 $('#addSubject').onclick=()=>{
  modal('Tạo môn học','<form id="subjectForm"><label>Tên môn học *</label><input name="name" required maxlength="80"><label>Mô tả</label><textarea name="description" rows="2"></textarea></form>');
  $('#modalSubmit').onclick=async()=>{
   const f=$('#subjectForm');if(!f.reportValidity())return;
   const d=new FormData(f),{error}=await window.studyloadSupabase.rpc('admin_create_subject',{p_name:d.get('name'),p_description:d.get('description')||null});
   if(error){toast('Không tạo được môn học: '+error.message);return}
   closeModal();await reloadStudyLoadDomain();render();toast('Đã tạo môn học.');
  };
 };
}
function renderSettings(){let u=current();pageHead('Cài đặt & dữ liệu','Thiết lập lịch học và quản lý tài khoản.');$('#content').innerHTML=`<div class="grid"><div class="card span-6"><h2>Thời gian rảnh và bận</h2><p class="muted">Mặc định có thời gian học 16:00–22:00 ngày thường, 09:00–22:00 cuối tuần. Các khoảng bận bên dưới được trừ khỏi sức chứa.</p><button data-action="busy">+ Thêm khoảng bận lặp lại</button><div class="stack" style="margin-top:12px">${state.busy.filter(b=>b.ownerId===u.id).map(b=>`<div class="item"><div><div class="item-title">${esc(b.label)}</div><div class="item-meta">${b.start}–${b.end} · ${b.days.map(d=>['CN','T2','T3','T4','T5','T6','T7'][d]).join(', ')}</div></div><button class="small danger" data-action="delete-busy" data-id="${b.id}">Xóa</button></div>`).join('')||'<div class="empty">Chưa khai báo.</div>'}</div></div><div class="card span-6"><h2>Nhắc hạn</h2><label class="checkrow"><input id="studyOnly" type="checkbox" ${state.reminderSettings.studyOnly?'checked':''}> Chỉ nhắc trong thời gian học / rảnh đã khai báo</label><label>Mốc nhắc (giờ trước hạn, phân cách bằng dấu phẩy)</label><input id="reminderHours" value="${esc(state.reminderSettings.hours.join(', '))}"><div style="margin-top:12px"><button data-action="save-reminders">Lưu thay đổi</button></div><p class="footer-note">Nhắc hạn được kiểm tra khi ứng dụng đang mở.</p></div>${isAdmin()?`<div class="card span-12"><h2>Quản trị dữ liệu</h2><p class="muted">Chỉ quản trị viên được sao lưu, xuất và nhập dữ liệu.</p><div class="row"><button class="secondary" data-action="export">Xuất bản sao lưu JSON</button><button class="secondary" data-action="import">Nhập bản sao lưu JSON</button><input type="file" id="importFile" accept=".json,application/json" style="max-width:260px"></div><div id="adminRequests" class="stack" style="margin-top:16px"></div></div>`:''}<div class="card span-6"><h2>Tài khoản</h2><p>Đang đăng nhập: <b>${esc(u.name)}</b> (${isAdmin()?'quản trị viên':isTeacher()?'giáo viên':'học sinh'}).</p>${!isAdmin()&&!isTeacher()?'<button data-action="request-teacher">Yêu cầu quyền giáo viên</button>':''}<button class="secondary" data-action="logout" style="margin-left:8px">Đăng xuất</button><p class="footer-note">Tài khoản, lớp học, bài tập, tiến độ và dữ liệu dự án được quản lý bằng Supabase; cài đặt cá nhân được đồng bộ theo tài khoản.</p></div><div class="card span-6"><h2>Lịch học</h2><button class="secondary" data-action="recalc">Tính lại lịch học</button><button class="secondary" data-action="reset-timer">Dừng bộ đếm</button></div></div>`;if(isAdmin()){renderAdminRequests();renderSubjectManager();renderAdminUsers()}}
function modal(title,body,submitText='Lưu'){ $('#modalRoot').innerHTML=`<div class="modal-backdrop" id="backdrop"><div class="modal" role="dialog" aria-modal="true"><div class="between"><h2>${title}</h2><button class="secondary small" data-close>Đóng</button></div>${body}<div class="modal-footer"><button class="secondary" data-close>Hủy</button><button id="modalSubmit">${submitText}</button></div></div></div>`;$('#backdrop').addEventListener('click',e=>{if(e.target.id==='backdrop')closeModal()});$('[data-close]').forEach(b=>b.onclick=closeModal)}
function closeModal(){$('#modalRoot').innerHTML=''}
function taskForm(t={},ownerId=current().id){
 const teachers=state.users.filter(u=>u.role==='teacher');
 if(isTeacher()){
  const classes=state.classes.filter(c=>isAdmin()||c.teacherIds.includes(current().id));
  const chosenClass=t.classId||classes[0]?.id||'';
  const subjects=(state.subjects||[]);
  const classOptions=classes.map(c=>'<option value="'+esc(c.id)+'" '+(c.id===chosenClass?'selected':'')+'>'+esc(c.name)+'</option>').join('');
  const eligibleSubjects=isAdmin()?subjects:subjects.filter(x=>(state.subjectAssignments||[]).some(a=>a.teacher_id===current().id&&a.subject_id===x.id));
  const subjectOptions=eligibleSubjects.map(x=>'<option value="'+esc(x.id)+'" '+(t.subjectId===x.id?'selected':'')+'>'+esc(x.name)+'</option>').join('');
  return '<form id="taskForm"><div class="form-grid"><div class="full"><label>Tên nhiệm vụ *</label><input name="title" required value="'+esc(t.title||'')+'"></div><div><label>Lớp *</label><select name="classId" required>'+classOptions+'</select></div><div><label>Môn học *</label><select name="subjectId" required><option value="">Chọn môn học</option>'+subjectOptions+'</select></div><div><label>Thời lượng dự kiến (phút) *</label><input type="number" name="estimatedMinutes" min="1" required value="'+(t.estimatedMinutes||60)+'"></div><div><label>Hạn nộp *</label><input type="datetime-local" name="dueAt" required value="'+esc(t.dueAt?new Date(new Date(t.dueAt).getTime()-new Date(t.dueAt).getTimezoneOffset()*60000).toISOString().slice(0,16):'')+'"></div><div><label>Ưu tiên</label><select name="priority"><option value="low" '+(t.priority===1?'selected':'')+'>Thấp</option><option value="normal" '+(!t.priority||t.priority===2?'selected':'')+'>Bình thường</option><option value="high" '+(t.priority===3?'selected':'')+'>Cao</option></select></div></div><p class="muted">Bài tập sẽ được tạo cho cả lớp. Mỗi học sinh có một bản ghi tiến độ riêng trong Supabase.</p></form>';
 }
 return '<form id="taskForm"><div class="form-grid"><div class="full"><label>Tên nhiệm vụ *</label><input name="title" required value="'+esc(t.title||'')+'"></div><div><label>Môn học *</label><input name="subject" required value="'+esc(t.subject||'')+'"></div><div><label>Loại nhiệm vụ</label><input name="kind" value="'+esc(t.kind||'Nhiệm vụ')+'"></div><div><label>Thời gian dự kiến (phút) *</label><input type="number" name="estimatedMinutes" min="1" required value="'+(t.estimatedMinutes??60)+'"></div><div><label>Thời gian cần học thêm (phút) *</label><input type="number" name="remainingWorkMinutes" min="0" required value="'+(t.remainingWorkMinutes??t.estimatedMinutes??60)+'"></div><div><label>Hạn nộp *</label><input type="datetime-local" name="dueAt" required value="'+esc(t.dueAt?new Date(new Date(t.dueAt).getTime()-new Date(t.dueAt).getTimezoneOffset()*60000).toISOString().slice(0,16):'')+'"></div><div><label>Ưu tiên</label><select name="priority"><option value="1" '+(t.priority===1?'selected':'')+'>Thường</option><option value="2" '+(!t.priority||t.priority===2?'selected':'')+'>Vừa</option><option value="3" '+(t.priority===3?'selected':'')+'>Cao</option></select></div></div></form>';
}
function openTask(t){
 modal(t?'Sửa nhiệm vụ':'Tạo nhiệm vụ mới',taskForm(t||{},current().id));
 $('#modalSubmit').onclick=async()=>{
  const f=$('#taskForm');if(!f.reportValidity())return;
  const d=new FormData(f),due=new Date(d.get('dueAt'));
  if(!Number.isFinite(+due)){toast('Hạn nộp không hợp lệ.');return}
  const est=Number(d.get('estimatedMinutes'));if(est<1){toast('Thời lượng không hợp lệ.');return}
  if(isTeacher()){
   const classId=d.get('classId'),subjectId=d.get('subjectId'),subject=(state.subjects||[]).find(x=>x.id===subjectId);
   if(!classId||!subject){toast('Chọn lớp và môn học hợp lệ.');return}
   const row={title:d.get('title'),description:null,subject_id:subjectId,class_id:classId,teacher_id:isAdmin()?null:current().id,estimated_minutes:est,deadline:due.toISOString(),scheduled_date:null,priority:d.get('priority')||'normal',created_by:current().id,source:isAdmin()?'admin':'teacher'};
   const query=t?.remoteAssignmentId?window.studyloadSupabase.from('assignments').update(row).eq('id',t.remoteAssignmentId):window.studyloadSupabase.from('assignments').insert(row).select('id').single();
   const {data:created,error}=await query;
   if(error){toast('Không lưu được bài tập: '+error.message);return}
   if(!t)state.classes.find(x=>x.id===classId)?.studentIds.filter(id=>id!==current().id).forEach(id=>notifyUser(id,'Bài tập mới được giao',d.get('title'),'assignment',created?.id));
   closeModal();await reloadStudyLoadDomain();schedule(classId);render();toast(t?'Đã cập nhật bài tập lớp.':'Đã giao bài tập cho cả lớp.');
   return;
  }
  if(t){
   Object.assign(t,{title:d.get('title'),subject:d.get('subject'),kind:d.get('kind'),estimatedMinutes:est,remainingWorkMinutes:Number(d.get('remainingWorkMinutes')),dueAt:due.toISOString(),priority:+d.get('priority')});
   t.history.push({at:iso(now()),field:'task',note:'Thông tin nhiệm vụ được chỉnh sửa'});
  }else state.tasks.push({id:uid('t'),ownerId:current().id,title:d.get('title'),subject:d.get('subject'),kind:d.get('kind'),estimatedMinutes:est,actualMinutes:0,remainingWorkMinutes:Number(d.get('remainingWorkMinutes')),dueAt:due.toISOString(),priority:+d.get('priority'),status:'todo',sessions:[],history:[],teacherId:null,classId:null,source:'personal'});
  closeModal();state.tasks.forEach(x=>{if(x.status!=='done'&&new Date(x.dueAt)<now())x.status='overdue'});schedule(current().id);save();render();toast('Đã lưu nhiệm vụ cá nhân và tính lại lịch.');
 };
}
function taskDetail(id){let t=state.tasks.find(x=>x.id===id);if(!t)return;let u=current();if(isStudent()&&t.ownerId!==u.id){toast('Bạn không có quyền xem nhiệm vụ này.');return}if(isTeacher()&&!allowedTaskIds(u).has(t.id)){toast('Ngoài phạm vi quyền truy cập.');return}let risk=(t.unscheduledMinutes||0)>0,logs=(t.sessions||[]).slice().reverse();modal('Chi tiết nhiệm vụ',`<div class="stack"><div class="item-title">${esc(t.title)}</div><div class="item-meta">${esc(t.subject)} · ${esc(t.kind||'')}</div>${risk?`<div class="notice red">Có nhiệm vụ có nguy cơ trễ hạn. Thời gian còn lại: ${t.remainingWorkMinutes} phút; thời gian chưa thể xếp lịch: ${t.unscheduledMinutes} phút. Hạn: ${fmtDate(t.dueAt)}.</div>`:''}<div class="grid"><div class="card span-6"><div class="stat-label">Thời gian dự kiến ban đầu</div><div class="stat">${t.estimatedMinutes}m</div></div><div class="card span-6"><div class="stat-label">Thực tế đã xác nhận</div><div class="stat">${t.actualMinutes}m</div></div><div class="card span-6"><div class="stat-label">Thời gian cần học thêm</div><div class="stat">${t.remainingWorkMinutes}m</div></div><div class="card span-6"><div class="stat-label">Hạn nộp</div><b>${fmtDate(t.dueAt)}</b></div></div><p>Trạng thái: <b>${esc(taskStatus(t))}</b> · Ưu tiên: ${t.priority===3?'Cao':t.priority===2?'Vừa':'Thường'}</p><div class="row">${isStudent()&&t.status!=='done'?`<button data-action="study" data-id="${t.id}">Bắt đầu học</button><button class="secondary" data-action="complete" data-id="${t.id}">Đánh dấu hoàn thành</button><button class="secondary" data-action="edit-progress" data-id="${t.id}">Cập nhật tiến độ</button>`:''}${isTeacher()?`<button class="secondary" data-action="edit-task" data-id="${t.id}">Sửa thông tin đã giao</button>`:''}</div><h3>Phiên học và lịch sử</h3>${logs.map(s=>`<div class="item"><div><div class="item-title">${s.completed?'✓ Phiên đã ghi nhận':'Phiên dự kiến'}</div><div class="item-meta">${fmtDate(s.startAt)} · ${s.minutes} phút ${s.paused?'· Có tạm dừng':''}</div></div></div>`).join('')||'<div class="empty">Chưa có phiên học.</div>'}<h3>Lịch sử tiến độ</h3>${(t.history||[]).map(h=>`<div class="item"><div><div>${esc(h.note||h.field||'Cập nhật')}</div><div class="item-meta">${fmtDate(h.at)}</div></div></div>`).join('')||'<div class="muted">Chưa có cập nhật nào.</div>'}</div>${t.remoteProgressId&&isStudent()?'<div class="section-head"><h3>Minh chứng bài tập</h3><button class="small" id="uploadAssignmentEvidence">+ Nộp minh chứng</button></div>'+((state.assignmentEvidence||[]).filter(x=>x.progress_id===t.remoteProgressId).map(x=>'<div class="item"><div><div class="item-title">'+esc(x.note||'Tệp minh chứng')+'</div><div class="item-meta">'+fmtDate(x.created_at)+'</div></div>'+(x.file_path?'<button class="small secondary" data-assignment-evidence-open="'+x.id+'">Mở</button>':'')+'</div>').join('')||'<div class="muted">Chưa có minh chứng.</div>'):''}</div>`,'Đóng');$('#modalSubmit').onclick=closeModal;$('#uploadAssignmentEvidence')?.addEventListener('click',()=>uploadAssignmentEvidence(t));$$('[data-assignment-evidence-open]').forEach(b=>b.onclick=async()=>{const x=(state.assignmentEvidence||[]).find(z=>z.id===b.dataset.assignmentEvidenceOpen);if(!x?.file_path)return;const {data,error}=await window.studyloadSupabase.storage.from('assignment-evidence').createSignedUrl(x.file_path,60);if(error){toast(error.message);return}window.open(data.signedUrl,'_blank','noopener')})}
function uploadAssignmentEvidence(t){
 modal('Nộp minh chứng bài tập','<form id="assignmentEvidenceForm"><label>Tệp minh chứng (tối đa 5 MB)</label><input type="file" name="file" accept="image/*,.pdf,.doc,.docx,.txt"><label>Ghi chú</label><textarea name="note" rows="3"></textarea></form>');
 $('#modalSubmit').onclick=async()=>{const f=$('#assignmentEvidenceForm'),file=f.elements.file.files[0],note=new FormData(f).get('note');if(!file&&!String(note||'').trim()){toast('Chọn tệp hoặc nhập ghi chú.');return}let path=null;if(file){if(file.size>5*1024*1024){toast('Tệp vượt quá 5 MB.');return}path=current().id+'/'+t.remoteProgressId+'/'+Date.now()+'_'+file.name.replace(/[^a-zA-Z0-9._-]/g,'_');const up=await window.studyloadSupabase.storage.from('assignment-evidence').upload(path,file);if(up.error){toast('Tải tệp thất bại: '+up.error.message);return}}const r=await window.studyloadSupabase.from('assignment_evidence').insert({progress_id:t.remoteProgressId,student_id:current().id,file_path:path,note:String(note||'').trim()||null});if(r.error){if(path)await window.studyloadSupabase.storage.from('assignment-evidence').remove([path]);toast('Không lưu được minh chứng: '+r.error.message);return}closeModal();await reloadStudyLoadDomain();render();taskDetail(t.id);toast('Đã nộp minh chứng bài tập.')};
}
function editProgress(t){modal('Cập nhật tiến độ',`<form id="progressForm"><p class="muted">Thời gian dự kiến ban đầu (${t.estimatedMinutes} phút) không thay đổi. Tiến độ không được suy ra tự động từ thời gian đã học.</p><label>Thời gian thực tế đã học được xác nhận (phút)</label><input type="number" min="0" name="actual" required value="${t.actualMinutes}"><label>Thời gian cần học thêm (phút)</label><input type="number" min="0" name="remaining" required value="${t.remainingWorkMinutes}"><label>Ghi chú tiến độ (không bắt buộc)</label><textarea name="note" rows="2" placeholder="Ví dụ: đã hoàn thành phần 1, còn phần 2"></textarea></form>`);$('#modalSubmit').onclick=()=>{let f=$('#progressForm');if(!f.reportValidity())return;let d=new FormData(f),a=+d.get('actual'),r=+d.get('remaining');if(a<0||r<0)return; t.actualMinutes=a;t.remainingWorkMinutes=r;t.history.push({at:iso(now()),field:'progress',note:d.get('note')||`Cập nhật tiến độ: thực tế ${a} phút, còn lại ${r} phút`});closeModal();schedule(t.ownerId);render();toast('Đã cập nhật tiến độ và lịch tương lai.')}}
function startStudy(t){if(timer.status!=='idle'){if(timer.taskId===t.id){showTimer(t);return}if(!confirm('Một đồng hồ khác đang hoạt động. Tạm dừng và chuyển nhiệm vụ?'))return;pauseTimer(false)}timer={taskId:t.id,status:'running',accum:0,startedAt:Date.now(),autoPausePrompted:false};t.status='doing';save();showTimer(t);timerInterval=setInterval(tick,1000)}
function elapsed(){return timer.accum+(timer.status==='running'&&timer.startedAt?Math.floor((Date.now()-timer.startedAt)/1000):0)}
function tick(){let t=state.tasks.find(x=>x.id===timer.taskId);if(!t){clearInterval(timerInterval);return}let sec=elapsed();if(sec>=Math.max(1,t.estimatedMinutes)*120&&!timer.autoPausePrompted){timer.autoPausePrompted=true;modal('Bạn còn học không?',`<p>Đồng hồ đã chạy đạt hai lần thời gian dự kiến (${t.estimatedMinutes*2} phút). Bạn còn học không?</p><p class="muted">Nếu không phản hồi trong 30 giây, đồng hồ tự tạm dừng.</p>`,'Tiếp tục học');let decided=false;$('#modalSubmit').onclick=()=>{decided=true;closeModal();timer.autoPausePrompted=false};window.__autoPauseTimeout=setTimeout(()=>{if(!decided&&timer.status==='running'){pauseTimer(false);closeModal();toast('Bạn đã tạm dừng.');showTimer(t)}},30000);$('#backdrop').querySelector('[data-close]').onclick=()=>{decided=true;closeModal();pauseTimer(false);showTimer(t)}}
if($('#timerSeconds'))$('#timerSeconds').textContent=clock(sec)}
function clock(s){return `${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor(s%3600/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function pauseTimer(rerender=true){if(timer.status!=='running')return;timer.accum=elapsed();timer.startedAt=null;timer.status='paused';clearInterval(timerInterval);save();if(rerender)showTimer(state.tasks.find(t=>t.id===timer.taskId))}
function resumeTimer(){if(timer.status!=='paused')return;clearInterval(timerInterval);timer.status='running';timer.startedAt=Date.now();timer.autoPausePrompted=false;timerInterval=setInterval(tick,1000);showTimer(state.tasks.find(t=>t.id===timer.taskId))}
function showTimer(t){let seconds=elapsed();modal('Bấm giờ học',`<div class="stack"><div class="item-title">${esc(t.title)}</div><div class="timer-readout" id="timerSeconds">${clock(seconds)}</div><div class="muted">Thời gian tạm dừng không được tính. Thời gian sẽ chỉ được lưu sau khi xác nhận hoàn thành.</div><div class="row">${timer.status==='running'?'<button class="secondary" id="pauseTimer">Tạm dừng</button>':'<button id="resumeTimer">Học tiếp</button>'}<button class="secondary" id="finishTimer">Hoàn thành</button></div></div>`,'Đóng');$('#modalSubmit').onclick=closeModal;$('#pauseTimer')?.addEventListener('click',()=>{pauseTimer(false);showTimer(t)});$('#resumeTimer')?.addEventListener('click',resumeTimer);$('#finishTimer')?.addEventListener('click',()=>confirmCompletion(t,Math.ceil(elapsed()/60),true))}
function confirmCompletion(t,minutes,fromTimer=false){modal('Xác nhận hoàn thành',`<p>Bạn xác nhận đã hoàn thành nhiệm vụ <b>${esc(t.title)}</b>?</p><form id="completeForm"><label>Thời gian thực tế đã học (phút) *</label><input type="number" name="minutes" min="0" required value="${fromTimer?minutes:''}" ${fromTimer?'':'placeholder="Nhập số phút thực tế"'}><label>Ngày học thực tế (nếu biết)</label><input type="date" name="studyDate" value="${fromTimer?localDay(now()):''}"><p class="muted">${fromTimer?'Kiểm tra hoặc chỉnh sửa số phút trước khi lưu.':'Không bấm giờ: bắt buộc nhập thời gian thực tế. Nếu không biết ngày học, hệ thống ghi nhận ngày hoàn thành.'}</p></form>`,'Xác nhận và lưu');$('#modalSubmit').onclick=()=>{let f=$('#completeForm');if(!f.reportValidity())return;let d=new FormData(f),m=Number(d.get('minutes'));if(!Number.isFinite(m)||m<0){toast('Thời gian thực tế không hợp lệ.');return}let studyDate=d.get('studyDate');let start=studyDate?new Date(studyDate+'T12:00:00'):now();t.actualMinutes=(+t.actualMinutes||0)+m;t.remainingWorkMinutes=0;t.status='done';t.sessions.push({id:uid('s'),startAt:iso(start),endAt:iso(now()),minutes:m,completed:true,planned:false,manual:!fromTimer,studyDateKnown:!!studyDate,paused:fromTimer&&timer.status==='paused'});t.history.push({at:iso(now()),field:'complete',note:`Học sinh xác nhận hoàn thành; thêm ${m} phút thực tế`});if(timer.taskId===t.id){timer={taskId:null,status:'idle',accum:0,startedAt:null,autoPausePrompted:false};clearInterval(timerInterval);clearTimeout(window.__autoPauseTimeout)}closeModal();schedule(t.ownerId);cancelTaskReminders(t.id);render();toast('Đã xác nhận hoàn thành và cập nhật lịch.')}}
function notifyUser(userId,title,body,type,taskId){
 if(userId!==current().id){
  window.studyloadSupabase.from('user_notifications').insert({user_id:userId,actor_id:current().id,title,body,notification_type:type||'activity',target_id:taskId?String(taskId):null}).then(({error})=>{if(error)console.warn('Shared notification not sent:',error.message)});
  return;
 }
 let key=type+'_'+(taskId||'')+'_'+title+'_'+body;
 let exists=state.notifications.some(n=>n.userId===userId&&n.key===key&&!n.dismissed);
 if(exists)return;
 state.notifications.push({id:uid('n'),userId,title,body,type,taskId,key,createdAt:iso(now()),read:false});save();
}
function cancelTaskReminders(id){state.notifications=state.notifications.filter(n=>n.taskId!==id||n.type==='project');save()}
function checkReminders(){let u=current(),count=0;for(let t of state.tasks.filter(t=>t.ownerId===u.id&&t.status!=='done')){let due=new Date(t.dueAt),hours=(due-now())/3600000;if(hours<0){cancelTaskReminders(t.id);continue}for(let h of state.reminderSettings.hours){if(hours<=h&&hours>h-0.15){if(state.reminderSettings.studyOnly&&!isFreeNow(u.id)){continue}let title=`Nhắc hạn còn ${h} giờ`,key=`reminder_${t.id}_${h}_${t.dueAt}`;if(!state.notifications.some(n=>n.key===key)){notifyUser(u.id,title,`${t.title} · còn ${Math.max(0,Math.round(hours*60))} phút tới hạn.`, 'reminder',t.id);count++}}}}save();render();toast(count?`Đã tạo ${count} nhắc hạn phù hợp.`:'Không có nhắc hạn mới cần hiển thị.')}
function isFreeNow(owner){let d=now(),ranges=rangesForDay(d,owner);return ranges.some(([a,b])=>d>=a&&d<b)}
function openBusy(){let u=current();modal('Thêm thời gian bận',`<form id="busyForm"><label>Tên khoảng bận *</label><input name="label" required placeholder="Học thêm, nghỉ ngơi…"><div class="form-grid"><div><label>Bắt đầu *</label><input type="time" name="start" required value="19:00"></div><div><label>Kết thúc *</label><input type="time" name="end" required value="20:00"></div></div><label>Ngày lặp lại</label><div class="member-grid">${['CN','T2','T3','T4','T5','T6','T7'].map((d,i)=>`<label class="checkrow"><input type="checkbox" name="days" value="${i}" ${i>0&&i<6?'checked':''}>${d}</label>`).join('')}</div></form>`);$('#modalSubmit').onclick=()=>{let f=$('#busyForm');if(!f.reportValidity())return;let d=new FormData(f),days=d.getAll('days').map(Number);if(!days.length){toast('Chọn ít nhất một ngày.');return}let [sh,sm]=d.get('start').split(':').map(Number),[eh,em]=d.get('end').split(':').map(Number);if(sh===eh&&sm===em){toast('Khoảng bận không thể dài 0 phút.');return}if(eh*60+em<sh*60+sm||eh*60+em>23*60){toast('Cảnh báo: khoảng bận kết thúc sau 11:00 PM hoặc qua nửa đêm. Vui lòng xác nhận cách khai báo.');if(!confirm('Khoảng thời gian kết thúc muộn hoặc qua nửa đêm. Vẫn lưu như đã nhập?'))return}state.busy.push({id:uid('b'),ownerId:u.id,label:d.get('label'),start:d.get('start'),end:d.get('end'),days,source:'user'});closeModal();schedule(u.id);save();render();toast('Đã lưu thời gian bận và tính lại lịch.')}}
function newClass(){
 if(!isAdmin()){toast('Chỉ quản trị viên mới được tạo lớp và thêm thành viên.');return}
 const teachers=state.users.filter(u=>u.role==='teacher'),students=state.users.filter(u=>u.role==='student');
 const teacherOptions=teachers.map(u=>'<option value="'+esc(u.id)+'">'+esc(u.name)+'</option>').join('');
 const studentOptions=students.map(u=>'<label class="checkrow"><input type="checkbox" name="students" value="'+esc(u.id)+'">'+esc(u.name)+'</label>').join('');
 const subjectOptions=(state.subjects||[]).map(sub=>'<div class="item"><span>'+esc(sub.name)+'</span><select name="subject_'+esc(sub.id)+'"><option value="">Chưa phân công</option>'+teacherOptions+'</select></div>').join('');
 modal('Tạo lớp học','<form id="classForm"><label>Tên lớp *</label><input name="name" required maxlength="80"><label>Năm học</label><input name="year" placeholder="2026–2027"><label>Mô tả</label><textarea name="description" rows="2"></textarea><label>Giáo viên chủ nhiệm *</label><select name="homeroom" required><option value="">Chọn giáo viên</option>'+teacherOptions+'</select><label>Giáo viên bộ môn (tùy chọn)</label>'+(subjectOptions||'<p class="muted">Chưa có môn học.</p>')+'<label>Học sinh tham gia</label><div class="member-grid">'+(studentOptions||'<p class="muted">Chưa có học sinh nào đăng ký.</p>')+'</div></form>');
 $('#modalSubmit').onclick=async()=>{
  const f=$('#classForm');if(!f.reportValidity())return;
  const d=new FormData(f),name=String(d.get('name')||'').trim(),homeroom=d.get('homeroom');
  if(!name||!homeroom){toast('Nhập tên lớp và chọn giáo viên chủ nhiệm.');return}
  const sb=window.studyloadSupabase;
  const {data:classId,error}=await sb.rpc('admin_create_class',{p_name:name,p_academic_year:d.get('year')||null,p_description:d.get('description')||null});
  if(error){toast('Không tạo được lớp: '+error.message);return}
  const {error:homeError}=await sb.rpc('admin_assign_homeroom_teacher',{p_class_id:classId,p_teacher_id:homeroom});
  if(homeError){toast('Đã tạo lớp nhưng chưa gán được GVCN: '+homeError.message);return}
  for(const studentId of d.getAll('students')){
   const {error:e}=await sb.rpc('admin_add_class_member',{p_class_id:classId,p_student_id:studentId});
   if(e){toast('Lớp đã tạo; thêm một học sinh thất bại: '+e.message);return}
  }
  for(const sub of (state.subjects||[])){
   const teacherId=d.get('subject_'+sub.id);if(!teacherId)continue;
   const {error:e}=await sb.rpc('admin_assign_subject_teacher',{p_class_id:classId,p_subject_id:sub.id,p_teacher_id:teacherId});
   if(e){toast('Lớp đã tạo; phân công môn '+sub.name+' thất bại: '+e.message);return}
  }
  closeModal();await reloadStudyLoadDomain();render();toast('Đã tạo lớp và lưu phân công lên Supabase.');
 };
}
function manageClass(classId){
 if(!isAdmin())return;
 const c=state.classes.find(x=>x.id===classId);if(!c)return;
 const available=state.users.filter(x=>x.role==='student'&&!c.studentIds.includes(x.id));
 const teachers=state.users.filter(x=>x.role==='teacher');
 const subjectOptions=(state.subjects||[]).map(sub=>{const currentAssignment=(state.subjectAssignments||[]).find(x=>x.class_id===c.id&&x.subject_id===sub.id);return '<div class="item"><span>'+esc(sub.name)+'</span><select name="subject_'+sub.id+'"><option value="">Không thay đổi</option>'+teachers.map(t=>'<option value="'+t.id+'" '+(currentAssignment?.teacher_id===t.id?'selected':'')+'>'+esc(t.name)+'</option>').join('')+'</select></div>'}).join('');
 modal('Quản lý lớp '+esc(c.name),'<form id="manageClassForm"><label>Tên lớp</label><input name="name" required value="'+esc(c.name)+'"><label>Năm học</label><input name="year" value="'+esc(c.academicYear||'')+'"><label>Mô tả</label><textarea name="description">'+esc(c.description||'')+'</textarea><label>Giáo viên chủ nhiệm</label><select name="homeroom">'+teachers.map(t=>'<option value="'+t.id+'" '+((c.homeroomTeacherIds||[]).includes(t.id)?'selected':'')+'>'+esc(t.name)+'</option>').join('')+'</select><label>Phân công giáo viên bộ môn</label>'+subjectOptions+'<label>Thêm học sinh</label>'+available.map(x=>'<label class="checkrow"><input type="checkbox" name="addStudents" value="'+x.id+'">'+esc(x.name)+'</label>').join('')+'<label>Gỡ học sinh khỏi lớp</label>'+c.studentIds.map(id=>'<label class="checkrow"><input type="checkbox" name="removeStudents" value="'+id+'">'+esc(state.users.find(x=>x.id===id)?.name||id)+'</label>').join('')+'</form>');
 $('#modalSubmit').onclick=async()=>{const f=$('#manageClassForm');if(!f.reportValidity())return;const d=new FormData(f),sb=window.studyloadSupabase;
  const update=await sb.from('classes').update({name:d.get('name'),academic_year:d.get('year')||null,description:d.get('description')||null}).eq('id',c.id);
  if(update.error){toast('Không cập nhật được lớp: '+update.error.message);return}
  const home=await sb.rpc('admin_assign_homeroom_teacher',{p_class_id:c.id,p_teacher_id:d.get('homeroom')});if(home.error){toast('Không cập nhật được GVCN: '+home.error.message);return}
  for(const id of d.getAll('addStudents')){const r=await sb.rpc('admin_add_class_member',{p_class_id:c.id,p_student_id:id});if(r.error){toast('Thêm học sinh thất bại: '+r.error.message);return}}
  for(const id of d.getAll('removeStudents')){const r=await sb.from('class_members').delete().eq('class_id',c.id).eq('student_id',id);if(r.error){toast('Gỡ học sinh thất bại: '+r.error.message);return}}
  for(const sub of state.subjects||[]){const teacherId=d.get('subject_'+sub.id);if(!teacherId)continue;const old=(state.subjectAssignments||[]).find(x=>x.class_id===c.id&&x.subject_id===sub.id);if(old?.teacher_id===teacherId)continue;const r=await sb.rpc('admin_assign_subject_teacher',{p_class_id:c.id,p_subject_id:sub.id,p_teacher_id:teacherId});if(r.error){toast('Phân công môn '+sub.name+' thất bại: '+r.error.message);return}}
  closeModal();await reloadStudyLoadDomain();render();toast('Đã cập nhật lớp và danh sách thành viên.');
 };
}
async function reloadStudyLoadDomain(){
 const sb=window.studyloadSupabase,userId=window.studyloadSessionUserId;
 const {data:authData}=await sb.auth.getUser();if(!authData||!authData.user)return;
 const {data:profile}=await sb.from('profiles').select('*').eq('id',userId).single();
 if(!profile)return;
 const {data:stored}=await sb.from('user_app_state').select('state').eq('user_id',userId).maybeSingle();
 state=await loadStudyLoadDomain(sb,profile,authData.user,stored&&stored.state?stored.state:emptyState());
 schedule(userId);
}
function assignTask(classId){let c=state.classes.find(c=>c.id===classId);openTask({classId,teacherId:current().id,estimatedMinutes:60,remainingWorkMinutes:60,priority:2},c.studentIds[0]||'stu1')}
function newProject(){
 const classes=state.classes.filter(c=>isAdmin()||(c.homeroomTeacherIds||[]).includes(current().id));
 if(!classes.length){toast('Chỉ quản trị viên hoặc giáo viên chủ nhiệm mới tạo được dự án lớp.');return}
 const options=classes.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.name)+'</option>').join('');
 modal('Tạo dự án nhóm','<form id="projectForm"><label>Tên dự án *</label><input name="name" required><label>Lớp *</label><select name="classId">'+options+'</select><label>Chia nhóm</label><select name="mode"><option value="auto">Tự động ngẫu nhiên</option><option value="manual">Một nhóm để tự chia sau</option></select><div class="form-grid"><div><label>Số nhóm</label><input type="number" min="1" name="groupCount" value="2"></div></div><p class="muted">Dự án, thành viên, nhóm và trưởng nhóm sẽ được lưu trong Supabase.</p></form>');
 $('#modalSubmit').onclick=async()=>{
  const f=$('#projectForm');if(!f.reportValidity())return;
  const d=new FormData(f),c=state.classes.find(x=>x.id===d.get('classId')),members=[...(c?.studentIds||[])];
  if(!c||!members.length){toast('Lớp chưa có học sinh.');return}
  const sb=window.studyloadSupabase;
  const {data:project,error}=await sb.from('projects').insert({name:d.get('name'),class_id:c.id,created_by:current().id,status:'active'}).select('id').single();
  if(error){toast('Không tạo được dự án: '+error.message);return}
  const {error:memberError}=await sb.from('project_members').insert(members.map((id,i)=>({project_id:project.id,user_id:id,member_role:'member'})));
  if(memberError){toast('Dự án đã tạo nhưng chưa thêm đủ thành viên: '+memberError.message);return}
  let groups=[];
  if(d.get('mode')==='auto'){
   const shuffled=[...members].sort(()=>Math.random()-.5),count=Math.max(1,Math.min(members.length,Number(d.get('groupCount'))||1));
   groups=Array.from({length:count},(_,i)=>({name:'Nhóm '+(i+1),memberIds:[]}));
   shuffled.forEach((id,i)=>groups[i%count].memberIds.push(id));
  }else groups=[{name:'Nhóm 1',memberIds:members}];
  for(const g of groups){
   const {data:teamId,error:teamError}=await sb.rpc('create_class_team',{p_class_id:c.id,p_name:g.name+' - '+project.id.slice(0,6),p_description:'Nhóm thuộc dự án '+d.get('name')});
   if(teamError){toast('Dự án đã tạo; tạo nhóm thất bại: '+teamError.message);continue}
   for(const id of g.memberIds){const {error:e}=await sb.rpc('add_class_team_member',{p_team_id:teamId,p_student_id:id});if(e)console.warn('Add team member:',e.message)}
   if(g.memberIds.length){
    const leader=g.memberIds[0];
    const {error:e}=await sb.rpc('assign_class_officer',{p_class_id:c.id,p_user_id:leader,p_role:'team_leader',p_team_id:teamId});
    if(e)console.warn('Assign team leader:',e.message);
   }
  }
  closeModal();await reloadStudyLoadDomain();render();const p=state.projects.find(x=>x.id===project.id);if(p)projectDetail(p.id);toast('Đã lưu dự án, thành viên và nhóm trên Supabase.');
 };
}
function projectDetail(id){let p=state.projects.find(x=>x.id===id);if(!p)return;let u=current(),canTeacher=isTeacher()&&p.teacherIds.includes(u.id),group=p.groups.find(g=>g.memberIds.includes(u.id)),canView=canTeacher||!!group||p.memberIds.includes(u.id);if(!canView){toast('Bạn không có quyền xem dự án này.');return}let body=`<div class="stack"><p class="muted">${esc(state.classes.find(c=>c.id===p.classId)?.name||'')} · Thành viên dự án: ${p.memberIds.length}</p><div class="between"><h3>Nhóm</h3>${canTeacher?'<button class="small secondary" id="addGroup">+ Nhóm thủ công</button>':''}</div>${p.groups.map(g=>`<div class="item"><div><div class="item-title">${esc(g.name)} ${g.leaderId?'· Trưởng nhóm: '+esc(state.users.find(x=>x.id===g.leaderId)?.name||''): '· Không có trưởng nhóm'}</div><div class="item-meta">${g.memberIds.map(mid=>esc(state.users.find(x=>x.id===mid)?.name||'')).join(', ')||'Chưa có thành viên'}</div></div>${canTeacher?`<button class="small secondary" data-action="edit-group" data-id="${g.id}" data-project="${p.id}">Sửa nhóm</button>`:''}</div>`).join('')}<div class="between"><h3>Nhiệm vụ dự án</h3>${(canTeacher||group)?'<button class="small" id="addProjectTask">+ Nhiệm vụ</button>':''}</div>${p.tasks.map(t=>{let taskGroup=p.groups.find(g=>g.memberIds.includes(t.assigneeId)),canLeaderComplete=!!group&&group.leaderId===u.id&&group.id===taskGroup?.id&&t.status!=='Hoàn thành';return `<div class="item"><div><div class="item-title">${esc(t.title)}</div><div class="item-meta">Giao: ${esc(state.users.find(x=>x.id===t.assigneeId)?.name||'Chưa giao')} · ${t.estimatedMinutes} phút · ${fmtDate(t.dueAt)} · ${esc(t.status)}</div><div class="item-meta">Đóng góp: ${(t.contributors||[]).map(x=>esc(state.users.find(u=>u.id===x)?.name||'')).join(', ')||'Chưa ghi nhận'}</div></div>${canLeaderComplete?`<button class="small" data-action="complete-project-task" data-id="${t.id}" data-project="${p.id}">Đánh dấu hoàn thành</button>`:''}</div>`}).join('')||'<div class="empty">Chưa có nhiệm vụ dự án.</div>'}<div class="between"><h3>Minh chứng</h3>${group?'<button class="small" id="submitEvidence">+ Nộp minh chứng</button>':''}</div>${p.evidence.filter(e=>canTeacher||e.groupId===group?.id).map(e=>`<div class="item"><div><div class="item-title">${esc(e.title)} <span class="badge ${e.status==='Đã xác nhận'?'green':e.status==='Yêu cầu sửa'?'red':'amber'}">${esc(e.status)}</span></div><div class="item-meta">Nhóm: ${esc(p.groups.find(g=>g.id===e.groupId)?.name||'')} · Nộp bởi ${esc(state.users.find(x=>x.id===e.submittedBy)?.name||'')} · ${esc(e.text||'')} ${e.url?`<a href="${esc(e.url)}" target="_blank" rel="noopener">Mở liên kết</a>`:''} ${e.filePath?`<button class="small secondary" data-project-file-open="${e.id}" data-file-kind="evidence">Mở tệp</button>`:''}</div></div><div class="actions">${canTeacher?`<button class="small secondary" data-action="evidence-status" data-id="${e.id}" data-project="${p.id}" data-status="Đã xác nhận">Xác nhận</button><button class="small secondary" data-action="evidence-status" data-id="${e.id}" data-project="${p.id}" data-status="Yêu cầu sửa">Yêu cầu sửa</button>`:''}${(group?.id===e.groupId&&(group.leaderId===u.id||!group.leaderId))?`<button class="small danger" data-action="delete-evidence" data-id="${e.id}" data-project="${p.id}">Xóa</button>`:''}</div></div>`).join('')||'<div class="empty">Không có minh chứng trong phạm vi quyền truy cập.</div>'}<h3>Tài liệu dự án</h3>${p.resources.filter(r=>canTeacher||r.groupId==null||r.groupId===group?.id).map(r=>`<div class="item"><div><div class="item-title">${esc(r.name)}</div><div class="item-meta">${esc(r.description||'')} ${r.url?`· <a href="${esc(r.url)}" target="_blank" rel="noopener">Mở</a>`:''} ${r.filePath?`<button class="small secondary" data-project-file-open="${r.id}" data-file-kind="resource">Mở tệp</button>`:''} · Người tải: ${esc(state.users.find(x=>x.id===r.ownerId)?.name||'')}</div></div>${canTeacher||r.ownerId===u.id?`<button class="small danger" data-action="delete-resource" data-id="${r.id}" data-project="${p.id}">Xóa</button>`:''}</div>`).join('')||'<div class="muted">Chưa có tài liệu dự án.</div>'}<button class="secondary" id="addResource">+ Tài liệu dự án</button></div>`;
modal(`Dự án: ${esc(p.name)}`,body,'Đóng');$('#modalSubmit').onclick=closeModal;
$('#addGroup')?.addEventListener('click',()=>editGroup(p,null));$$('[data-action="edit-group"]').forEach(b=>b.onclick=()=>{closeModal();editGroup(p,p.groups.find(g=>g.id===b.dataset.id))});
$('#addProjectTask')?.addEventListener('click',()=>{closeModal();projectTaskForm(p,group||p.groups[0])});$('#submitEvidence')?.addEventListener('click',()=>{closeModal();evidenceForm(p,group)});$('#addResource')?.addEventListener('click',()=>{closeModal();resourceForm(p,group)});$('[data-project-file-open]').forEach(b=>b.onclick=async()=>{const item=b.dataset.fileKind==='evidence'?p.evidence.find(x=>x.id===b.dataset.projectFileOpen):p.resources.find(x=>x.id===b.dataset.projectFileOpen);if(!item?.filePath)return;const {data,error}=await window.studyloadSupabase.storage.from('project-files').createSignedUrl(item.filePath,60);if(error){toast(error.message);return}window.open(data.signedUrl,'_blank','noopener')});}
function editGroup(p,g){
 const c=state.classes.find(x=>x.id===p.classId);if(!c)return;
 const members=c.studentIds.filter(id=>!p.groups.some(x=>x.id!==g?.id&&x.memberIds.includes(id)));
 const memberOptions=members.map(id=>'<label class="checkrow"><input type="checkbox" name="members" value="'+esc(id)+'" '+((g?.memberIds||[]).includes(id)?'checked':'')+'>'+esc(state.users.find(u=>u.id===id)?.name||'')+'</label>').join('');
 const leaderOptions=members.filter(id=>(g?.memberIds||[]).includes(id)||!p.groups.some(x=>x.memberIds.includes(id))).map(id=>'<option value="'+esc(id)+'" '+(g?.leaderId===id?'selected':'')+'>'+esc(state.users.find(u=>u.id===id)?.name||'')+'</option>').join('');
 modal(g?'Sửa nhóm':'Thêm nhóm','<form id="groupForm"><label>Tên nhóm *</label><input name="name" required value="'+esc(g?.name||'Nhóm mới')+'"><label>Thành viên (mỗi học sinh chỉ thuộc một nhóm trong dự án)</label>'+memberOptions+'<label>Trưởng nhóm (không bắt buộc)</label><select name="leader"><option value="">Không có trưởng nhóm</option>'+leaderOptions+'</select></form>');
 $('#modalSubmit').onclick=async()=>{
  const f=$('#groupForm');if(!f.reportValidity())return;
  const d=new FormData(f),ids=d.getAll('members'),leader=d.get('leader')||null;
  if(leader&&!ids.includes(leader)){toast('Trưởng nhóm phải là thành viên nhóm.');return}
  const sb=window.studyloadSupabase;
  if(g?.remote){
   const removed=g.memberIds.filter(id=>!ids.includes(id)),added=ids.filter(id=>!g.memberIds.includes(id));
   if(removed.length&&p.tasks.some(t=>removed.includes(t.assigneeId)&&t.status!=='Hoàn thành')&&!confirm('Có nhiệm vụ chưa hoàn thành. Lưu thay đổi thành viên và giữ nguyên lịch sử nhiệm vụ?'))return;
   for(const id of removed){const {error}=await sb.rpc('remove_class_team_member',{p_team_id:g.id,p_student_id:id});if(error){toast('Không thể gỡ thành viên: '+error.message);return}}
   for(const id of added){const {error}=await sb.rpc('add_class_team_member',{p_team_id:g.id,p_student_id:id});if(error){toast('Không thể thêm thành viên: '+error.message);return}}
   const {error:renameError}=await sb.from('class_teams').update({name:d.get('name')}).eq('id',g.id);
   if(renameError){toast('Không đổi được tên nhóm: '+renameError.message);return}
   if(g.leaderId!==leader){
    if(g.leaderRoleId){const {error}=await sb.rpc('revoke_class_officer',{p_officer_role_id:g.leaderRoleId});if(error){toast('Không thu hồi được trưởng nhóm cũ: '+error.message);return}}
    if(leader){const {error}=await sb.rpc('assign_class_officer',{p_class_id:c.id,p_user_id:leader,p_role:'team_leader',p_team_id:g.id});if(error){toast('Không gán được trưởng nhóm mới: '+error.message);return}}
   }
  }else{
   const {data:teamId,error}=await sb.rpc('create_class_team',{p_class_id:c.id,p_name:d.get('name')+' - '+p.id.slice(0,6),p_description:'Nhóm dự án '+p.name});
   if(error){toast('Không tạo được nhóm: '+error.message);return}
   for(const id of ids){const {error:e}=await sb.rpc('add_class_team_member',{p_team_id:teamId,p_student_id:id});if(e){toast('Nhóm đã tạo nhưng thêm thành viên lỗi: '+e.message);return}}
   if(leader){const {error:e}=await sb.rpc('assign_class_officer',{p_class_id:c.id,p_user_id:leader,p_role:'team_leader',p_team_id:teamId});if(e){toast('Nhóm đã tạo nhưng chưa gán được trưởng nhóm: '+e.message);return}}
  }
  closeModal();await reloadStudyLoadDomain();render();projectDetail(p.id);toast('Đã cập nhật nhóm trên Supabase.');
 };
}
function projectTaskForm(p,g){
 const members=g?.memberIds||p.memberIds||[];
 if(!isTeacher()&&(!g||g.leaderId!==current().id)){toast('Chỉ giáo viên phụ trách hoặc trưởng nhóm được giao nhiệm vụ.');return}
 const opts=members.map(id=>'<option value="'+esc(id)+'">'+esc(state.users.find(u=>u.id===id)?.name||'Thành viên')+'</option>').join('');
 modal('Tạo nhiệm vụ dự án','<form id="ptForm"><label>Tên nhiệm vụ *</label><input name="title" required><label>Người thực hiện *</label><select name="assignee" required>'+opts+'</select><div class="form-grid"><div><label>Thời lượng dự kiến (phút)</label><input type="number" min="1" name="minutes" value="60" required></div><div><label>Hạn nộp *</label><input type="datetime-local" name="due" required></div></div></form>');
 $('#modalSubmit').onclick=async()=>{
  const f=$('#ptForm');if(!f.reportValidity())return;
  const d=new FormData(f);
  const {error}=await window.studyloadSupabase.rpc('create_project_task',{p_project_id:p.id,p_title:d.get('title'),p_description:null,p_assigned_to:d.get('assignee'),p_estimated_minutes:Number(d.get('minutes')),p_deadline:new Date(d.get('due')).toISOString()});
  if(error){toast('Không tạo được nhiệm vụ dự án: '+error.message);return}
  if(d.get('assignee'))notifyUser(d.get('assignee'),'Nhiệm vụ dự án mới',d.get('title'),'project-task',p.id);
  closeModal();await reloadStudyLoadDomain();render();projectDetail(p.id);toast('Đã lưu nhiệm vụ dự án.');
 };
}
function evidenceForm(p,g){
 modal('Nộp minh chứng','<form id="evForm"><label>Tiêu đề *</label><input name="title" required><label>Văn bản / mô tả</label><textarea name="text" rows="3"></textarea><label>Liên kết ngoài</label><input type="url" name="url"><label>Tệp minh chứng (tối đa 10 MB)</label><input type="file" name="file" accept="image/*,.pdf,.doc,.docx,.txt"><label>Đóng góp của thành viên</label>'+g.memberIds.map(id=>'<label class="checkrow"><input type="checkbox" name="contributors" value="'+esc(id)+'" '+(id===current().id?'checked':'')+'>'+esc(state.users.find(u=>u.id===id)?.name||'')+'</label>').join('')+'</form>');
 $('#modalSubmit').onclick=async()=>{const f=$('#evForm');if(!f.reportValidity())return;const d=new FormData(f),file=f.elements.file.files[0];let path=null;if(file){if(file.size>10*1024*1024){toast('Tệp vượt quá 10 MB.');return}path=current().id+'/'+p.id+'/'+Date.now()+'_'+file.name.replace(/[^a-zA-Z0-9._-]/g,'_');const up=await window.studyloadSupabase.storage.from('project-files').upload(path,file);if(up.error){toast('Tải tệp thất bại: '+up.error.message);return}}const {error}=await window.studyloadSupabase.from('project_evidence').insert({project_id:p.id,group_id:g.id,title:d.get('title'),description:d.get('text')||null,external_url:d.get('url')||null,file_path:path,submitted_by:current().id,contributors:d.getAll('contributors'),status:'pending'});if(error){if(path)await window.studyloadSupabase.storage.from('project-files').remove([path]);toast('Không nộp được minh chứng: '+error.message);return}closeModal();await reloadStudyLoadDomain();render();projectDetail(p.id);p.memberIds.filter(id=>id!==current().id).forEach(id=>notifyUser(id,'Minh chứng nhóm mới',d.get('title'),'project'));p.teacherIds.forEach(id=>notifyUser(id,'Minh chứng chờ xác minh',d.get('title'),'project'))};
}
